    'cli.doctor.mode_split' => 'modalità {tui} nella TUI, {headless} per -p, {background} per i daemon avviati (valori predefiniti integrati)',
    'cli.doctor.no_problems' => 'Nessun problema rilevato.',
    'cli.doctor.pdo' => 'pdo_{driver} {state}; ext-sqlite3 {sqlite3} — l\'elenco task del Team apre SQLite3 direttamente',
    'cli.doctor.pdo_unusable' => 'NON UTILIZZABILE — l\'archivio sessioni non può aprire il database: {error}',
    'cli.doctor.pdo_usable' => 'utilizzabile',
    'cli.doctor.php' => '{version} in {binary}',
    'cli.doctor.php_too_old' => '{version} in {binary} (candy-code richiede PHP 8.3+)',
    'cli.doctor.provider' => '{provider} (modello {model})',
    'cli.doctor.provider_none' => 'nessuno selezionato — risponderà il backend echo offline (impostare CANDY_CODE_PROVIDER)',
    'cli.doctor.provider_shell' => 'backend shell-out (livello $CANDY_CODE_BACKEND_CMD)',
    'cli.doctor.provider_unconstructable' => '{provider} è selezionato ma non può essere istanziato: {error}',
    'cli.doctor.provider_unknown' => '{provider} è selezionato ma non è un provider noto — vedi `candy-code models`',
    'cli.doctor.sandbox_binary' => '{backend} in {path}',
    'cli.doctor.sandbox_binary_absent' => '{backend} non trovato nel PATH',
    'cli.doctor.sandbox_nonlinux' => 'bashSandbox "{mode}" è configurato ma bubblewrap è solo per Linux e questo host è {os}',
    'cli.doctor.sandbox_nonlinux_off' => 'bashSandbox è disattivato; bubblewrap è solo per Linux e questo host è {os}',
    'cli.doctor.sandbox_off' => 'bashSandbox è disattivato; {bwrap}, e la jail si avvierebbe qui se fosse abilitata',
    'cli.doctor.sandbox_off_blocked' => 'bashSandbox è disattivato; {bwrap}, e la jail non si avvierebbe qui nemmeno se fosse abilitata ({reason})',
    'cli.doctor.sandbox_ready' => 'bashSandbox "{mode}"; {bwrap}, e la jail si avvia',
    'cli.doctor.sandbox_refused' => 'bashSandbox "{mode}" è configurato ma la jail non si avvia ({reason}) — {remedy}',
    'cli.doctor.sandbox_remedy_apparmor' => 'installa bubblewrap, oppure aggiungi un profilo in /etc/apparmor.d che conceda a bwrap gli spazi dei nomi utente non privilegiati (il sysctl apparmor_restrict_unprivileged_userns è il fallback grossolano)',
    'cli.doctor.sandbox_remedy_generic' => 'installa bubblewrap, oppure imposta bashSandbox su "off"',
    'cli.doctor.sandbox_remedy_seatbelt' => 'verifica che /usr/bin/sandbox-exec funzioni ancora su questa installazione macOS, oppure imposta bashSandbox su "off"',
    'cli.doctor.server_ready' => 'pcntl, posix e ffi disponibili — `serve` può avviarsi',
    'cli.doctor.server_refuses' => '`serve` rifiuterà di avviarsi: {problems}',
    'cli.doctor.sessions' => '{count} sessioni archiviate',
    'cli.doctor.settings_clean' => 'ogni file di impostazioni contiene solo chiavi lette da candy-code',
    'cli.doctor.unknown' => 'sconosciuto',
    'cli.headless.permission_hint' => '  suggerimento: un\'esecuzione `-p` senza modalità nominata parte nella modalità `default` di richiesta; le richieste non presidiate non hanno nessuno che risponda, quindi falliscono in modo sicuro. Le esecuzioni scriptate possono specificare --permission-mode bypass-permissions (o accept-edits) per proseguire.',
    'cli.help.screen' => <<<'TXT'
CandyCode — assistente di programmazione AI per il terminale.

Uso:
  candy-code                       Avvia la TUI interattiva (predefinito)
  candy-code <dir>                 Avvia la TUI con radice <dir>, che deve
                                   esistere (solo come primo argomento)
  candy-code [<dir>] <parole…>     Avvia la TUI e invia le parole come
                                   primo prompt, es. candy-code fix the bug
  candy-code -c                    Continua la sessione più recente
  candy-code --resume [<id>]       Riprendi una sessione archiviata (selettore se senza id)
  candy-code -p <prompt>           Esegui un singolo prompt ed esci (one-shot)
  candy-code run "<prompt>"        Alias di -p "<prompt>" (modalità one-shot)
  candy-code --output-format json  Output JSON leggibile da macchina (one-shot)
  candy-code --worktree [<name>]   Esegui questa sessione in un git worktree
                                   proprio (creato se non esiste)

Sottocomandi (nessuno apre la TUI né richiede un provider, una chiave API o un
terminale; ognuno risponde ed esce, tranne serve e mcp serve, che restano in esecuzione fino a
arresto — e attach, che è l'eccezione a entrambi: esegue la TUI sulla sessione di un server in
esecuzione; acp esegue turni per un editor, finché l'editor non si disconnette):
  bundles list           Elenca i bundle di plugin visibili da questa directory: nome,
                         versione, livello e le superfici che ognuno porta —
                         inclusi gli hook e .mcp.json che candy-code
                         rifiuta di eseguire.
  bundles install <src>  Copia una directory di bundle, oppure clona un URL git con
                         un clone depth-one limitato, nella radice bundle utente
                         (~/.candy-code/bundles), dove solo tu ne sei proprietario.
  doctor                 Verifica questa installazione e segnala ogni problema
                         rilevato: versione PHP, le estensioni che l'archivio sessioni
                         e serve richiedono, il file di configurazione, la policy
                         dei permessi, il provider selezionato, il database delle sessioni
                         e la configurazione MCP del progetto. Esce con 1 se qualche controllo
                         FALLISCE.
                         Distinto dal tool "doctor" invocabile dal modello, che
                         segnala al modello il protocollo immagini del terminale.
  import claude          Anteprima dell'importazione delle impostazioni di Claude Code: legge l'utente di Claude
                         file di impostazioni, oltre al file di impostazioni .claude nella directory di avvio
                         root quando --project è specificato, traduce i suoi permessi
                         liste allow/deny/ask in permissionRules (il lato più restrittivo
                         vince sempre — deny prevale su allow), mappa il modello e assegna un nome a ogni
                         chiave per cui non ha una destinazione come saltata. Non viene scritto nulla finché
                         confermato: --yes accetta la anteprima stampata così com'è, e
                         senza di esso viene richiesto un terminale interattivo. I nomi di anteprima
                         ogni regola di autorizzazione che amplierebbe ciò che viene eseguito senza chiedere conferma.
  login <provider>       Accedi a un provider: claude-code e codex affidano la
                         terminale alla propria CLI (il token non passa mai
                         tramite candy-code); openai, anthropic e gemini
                         incolla una chiave nel blocco providers del file di configurazione;
                         il resto è il nome di chi possiede effettivamente la propria credenziale.
  models                 Elenca i provider che questa installazione può selezionare e i
                         modello predefinito per ciascuno; "*" indica quello selezionato
                         uno.
  session list [--all|--archived|--children] [--limit N]
                         Elenca le sessioni salvate, prima le bloccate, poi le più recenti
                         primo: id, ultimo aggiornamento, tipo, turni, provider/modello
                         e nome (★ indica una riga fissata). --children aggiunge
                         righe sub-agent e in background, --archived aggiunge
                         quelli archiviati, --all aggiunge entrambi; 20 righe a meno che
                         --limit dice il contrario.
  session show <target>  Stampa i dettagli e la trascrizione di una sessione.
  session import <path> [--format auto|…] [--name <title>] [--force]
                         Importa un file di trascrizione come nuova sessione:
                         un export candy-code o la cronologia di claude-code,
                         codex o opencode (--format nomina, auto individua).
  session rename <target> <title…>
                         Rinomina una sessione; le parole dopo la destinazione sono
                         il titolo.
  session delete <target> [--with-children]
                         Elimina una sessione. I sotto-agenti figli vengono eliminati con essa;
                         i rami vengono mantenuti a meno che non si usi --with-children.
  session pin|unpin|archive|unarchive <target>
                         Fissa una sessione (elencata per prima, mai eliminata), oppure
                         archiviarlo (nascosto dall'elenco predefinito, conservato).
                         <target> è un id, un nome o un prefisso id univoco.
                         Esce con 1 se non corrisponde nulla, con 2 se un prefisso è
                         ambiguo (i candidati sono elencati).
  mcp list               Elenca i server MCP dichiarati in .mcp.json, SENZA
                         avviandone alcuno. Segnala invece quando il file
                         è assente, risolve al di fuori dell'albero del progetto, oppure è
                         presente ma la radice del progetto non è attendibile.
  mcp auth login <server> [token-url] [authorize-url] [registration-url]
                         Autorizza con OAuth un server MCP dichiarato: apre
                         (o stampa) l'URL di autorizzazione, intercetta il
                         redirect loopback e salva i token per gli usi futuri.
  mcp trust              Approva il .mcp.json di questo progetto così com'è: aggiungi
                         la radice in "trustedProjectMcp" e registra ogni
                         comando, args e env del server, quindi una modifica successiva a
                         uno qualsiasi di essi viene rifiutato all'avvio fino alla riapprovazione.
                         Non avvia nulla.
  mcp import claude|opencode|claude-project <path> [--write user]
                         Traduci una config MCP esterna e stampa la
                         blocco .mcp.json equivalente su stdout. Stampa solo
                         per impostazione predefinita; --write user aggiunge in coda la traduzione
                         voci nel ~/.candy-code/mcp.json dell'utente
                         (una collisione di nomi rifiuta l'intera scrittura, e la
                         il livello del progetto non viene mai scritto). Le rinomine
                         le traduzioni effettuate sono elencate su stderr.
  mcp serve [--root PATH]
                         Esegui candy-code stesso come server MCP su stdio:
                         un frame JSON-RPC per riga in ingresso, una risposta per riga
                         in uscita, finché stdin non si chiude. Le chiamate a tool
                         eseguono il roster di sola lettura (Read, Glob, Grep, Ls, RepoMap), vincolato alla
                         radice del workspace, tramite il PermissionGate
                         del lancio e la catena di hook PreToolUse — questo è il server
                         MCP che un client può avviare; il WebSocket
                         `candy-code serve` non parla ancora MCP. Esegue finché
                         non viene fermato.
  lsp install <language> Installa il language server bloccato per un
                         linguaggio: il pacchetto npm o il binario di release
                         verificato con checksum, nella radice di installazione privata sotto
                         la tua home. `lsp list` risponde quali linguaggi sono
                         installabili.
  lsp list               Segnala ogni linguaggio installabile: la sua versione
                         bloccata, dove il suo server è installato (o che non lo è),
                         e se esiste una release per il SO e l'architettura
                         di questa macchina. Non avvia nulla,
                         non scarica nulla.
  self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]
                         Sostituisci questa installazione phar con l'ultima release
                         candy-code pubblicata, verificata sha256 contro il
                         sidecar di release PRIMA dello swap; il phar in esecuzione è
                         conservato come <phar>.old e --rollback ripristina esattamente
                         quella copia una volta. Quando una chiave pubblica di firma è bloccata
                         nella sorgente di release, la firma candy-code.phar.minisig
                         deve verificare anch'essa (--allow-unsigned salta
                         solo quella verifica). --check riporta solo corrente vs
                         ultima ed esce con 1 quando è disponibile un aggiornamento. Un'
                         installazione Composer viene rifiutata con chiarezza, indicando il
                         comando composer update da eseguire in alternativa. Un'
                         installazione dev-built segue la release rolling candy-code/dev
                         per impostazione predefinita (è aggiornata quando il commit
                         target della release corrisponde allo sha del timbro) e --channel
                         seleziona esplicitamente l'uno o l'altro ramo.
  serve [--host <ip>] [--port <n>] [--allow-remote] [--allowed-host <list>]
        [--allowed-ips <list>] [--allowed-origin <list>] [--allow-dir-browse]
        [--browse-root <dir>] [--web-root <dir>] [--no-web] [--allow-bypass]
        [--allow-root] [--detach] [--parent-pid <pid>]
        [--tls-cert <file>] [--tls-key <file>]
                         Esegue il server WebSocket + HTTP a cui si collega la UI web,
                         in foreground fino a Ctrl+C. Si associa a 127.0.0.1:7420
                         per impostazione predefinita e stampa un URL di accesso il cui codice
                         monouso viene scambiato con un cookie del browser; ogni client
                         ne ha bisogno, oppure del token in ~/.candy-code/server/token,
                         incluso il loopback. Opzioni:
      --host <ip>        Indirizzo a cui associarsi (predefinito 127.0.0.1; localhost e ::1
                         contano anch'essi come loopback). Qualsiasi altro indirizzo è rifiutato
                         a meno che non sia specificato anche --allow-remote.
      --port <n>         Porta a cui associarsi (predefinita 7420; 0 ne sceglie una libera).
      --allow-remote     Consente un --host non-loopback. Senza --tls-cert e
                         --tls-key è HTTP in chiaro: anteporre un reverse proxy TLS
                         oppure servire TLS direttamente (vedi sotto). Su
                         0.0.0.0 o :: il server risponde agli indirizzi propri della macchina
                         e l'URL di accesso li elenca.
      --tls-cert <file>  Certificato PEM con cui il listener stesso serve TLS,
                         da fornire insieme a --tls-key. L'URL di accesso
                         sarà allora https://, il cookie di sessione avrà Secure
                         e un client http:// in chiaro non riceverà alcuna risposta.
      --tls-key <file>   Chiave privata PEM per --tls-cert: un file leggibile senza
                         permessi di gruppo o mondo, corrispondente al certificato.
                         Una coppia errata o incompleta è rifiutata all'avvio.
      --allowed-host <list>
                         Nomi host aggiuntivi (o host:port) separati da virgola a cui
                         il server risponde, ad es. un nome DNS per questa macchina.
                         Ripetibile.
      --allowed-ips <list>
                         IP client o range CIDR separati da virgola (es.
                         1.2.3.4,10.0.0.0/8) autorizzati a connettersi; qualsiasi altro
                         indirizzo riceve 403 prima dell'accesso. Il loopback è
                         sempre consentito. Non impostato: nessun filtro indirizzi.
                         Ripetibile.
      --allowed-origin <list>
                         Origin del browser aggiuntivi separati da virgola
                         (http(s)://host[:port]) consentiti accanto a quello
                         proprio del server. Ripetibile.
      --allow-dir-browse Consente ai client autenticati di scegliere la directory in cui avviare
                         una nuova sessione: possono elencare nomi di directory (mai
                         file) sotto --browse-root. Disattivato per impostazione predefinita.
      --browse-root <dir>
                         La directory a cui --allow-dir-browse è limitato
                         (predefinita: la tua home directory).
      --web-root <dir>   Serve la UI web da <dir> invece del pacchetto
                         sugarcraft/candy-code-web installato.
      --no-web           Serve solo API e WebSocket, senza file UI.
      --allow-bypass     Consente alle sessioni di funzionare in bypass-permissions o dont-ask
                         (rifiutato per impostazione predefinita; le sessioni del server partono in
                         default salvo che --permission-mode non specifichi altrimenti).
      --allow-root       Consente l'esecuzione come root (rifiutato per impostazione predefinita).
      --detach           Esegue in background: stampa URL e pid una volta
                         associata la porta, poi esce; il server registra su
                         server.log nella sua directory di stato.
      --parent-pid <pid> Ferma il server quando il processo <pid> esce (per un
                         editor o TUI che avvia un server privato).
                         Rifiuta di avviarsi senza ext-pcntl, ext-posix e
                         ext-ffi (vedi doctor). Esce con 1 se la porta è occupata o
                         un server è già in esecuzione dalla stessa directory di stato.
  serve status           Riporta il server in esecuzione: pid, URL, root, uptime e
                         se GET /api/health risponde. Esce con 1 quando nessuno
                         è in esecuzione.
  serve stop [--force]   Ferma il server: SIGTERM, fino a 30 s per lo scarico, poi SIGKILL.
      --force            SIGKILL immediato.
  serve logs [-f]        Stampa la fine del log di un server distaccato.
  -f, --follow           Continua a stampare ciò che viene aggiunto fino all'arresto.
  serve url [--qr]       Stampa un URL di accesso con un nuovo codice monouso.
      --qr              Renderizza ogni URL di accesso come un codice QR terminale scansionabile.
  serve token [--rotate] Stampa il token owner che i client bearer inviano.
      --rotate           Lo sostituisce; un server in esecuzione mantiene il vecchio fino
                         al riavvio.
  attach [<session>] [--url <url>]
                         Esegue la TUI su una sessione di un candy-code
                         serve in esecuzione: il server gestisce ogni turno e i suoi tool, e
                         questo terminale li mostra e risponde alle domande
                         di permesso che sollevano. <session> è un id, un nome o un
                         prefisso id univoco di una delle sessioni del server;
                         senza di esso ne viene creata una nuova. Il server è
                         quello riportato da serve status, il cui token proviene da
                         CANDY_CODE_SERVER_TOKEN o dal file di token nella directory di stato.
                         Uscire distacca; un turno in esecuzione prosegue.
                         Esce con 1 se nessun server risponde.
      --url <url>        Si aggancia al server su <url> (l'indirizzo che serve
                         stampa) invece.
  acp                    Esegue come Agent Client Protocol agent: l'editor
                         (Zed, JetBrains, Neovim) lo avvia e comunica
                         JSON-RPC sul suo stdin e stdout. Le sessioni si aprono in
                         la radice del progetto dell'editor, i turni vengono eseguiti qui con il
                         provider e gli strumenti dell'installazione, e l'editor risponde
                         alle domande di autorizzazione. Non per un terminale: stdout
                         trasporta solo il protocollo (tutto il resto va a
                         stderr). Esce con 0 quando l'editor chiude stdin.
  completion bash|zsh|fish
                         Scrivi uno script di completamento shell su stdout, es.
                         eval "$(candy-code completion bash)".
  usage [7|30|all] [--session <target>]
                         Riepiloga il registro di spesa persistente per giorno e modello:
                         la stessa pagina che `/usage` stampa, sullo stesso
                         raggruppamento condiviso. 7 e 30 prendono giorni UTC interi, oggi incluso,
                         all (o nessun operando) copre l'intero registro, e una
                         finestra al di fuori di quell'insieme viene rifiutata anziché
                         essere allargata silenziosamente. --session restringe a una sessione
                         per id, nome o prefisso univoco; --output-format json
                         emette la mappa dei fatti da cui la pagina è stata costruita. Un
                         registro illeggibile indica il motivo ed esce con 1;
                         i dollari per raggruppamenti che includono un modello non prezzato
                         vengono stampati come limite inferiore ≥, mai come somma semplice.

Opzioni:
  -p, --prompt <text>    Fornisci un prompt sulla riga di comando (modalità one-shot)
      --output-format <format>
                         Formato di output: "text" (predefinito), "json" o
                         "stream-json" (eventi NDJSON, risposta per ultima)
      --root <dir>       Usa <dir> come radice del progetto invece della
                         directory corrente. Accetta anche --root=<dir> (la forma da usare
                         quando <dir> inizia con "-"); non può essere omessa.
                         Indicare una radice qui E come argomento posizionale viene
                         rifiutato anziché lasciare che una vinca silenziosamente.
      --config <file>    Leggi impostazioni, autorizzazioni e radici di hook attendibili da
                         <file> invece di ~/.candy-code/config.json. Accetta
                         anche --config=<file>. Deve già esistere, essere
                         leggibile, di tua proprietà, e né il file né la sua
                         directory possono essere scrivibili da tutti — contiene la
                         policy di autorizzazione, quindi è soggetto allo stesso standard
                         di ~/.candy-code/config.json (un file sotto /etc o
                         /tmp viene normalmente rifiutato per uno di quei motivi).
                         Solo il FILE si sposta: agenti, skill, workflow,
                         sessioni e memoria restano in ~/.candy-code.
      --model <name>     Usa <name> come modello di conversazione, sovrascrivendo
                         $CANDY_CODE_MODEL e il predefinito del provider. Accetta
                         anche --model=<name>. Seleziona un modello, non un provider
                         — il provider proviene ancora da $CANDY_CODE_PROVIDER o
                         dall'impostazione `provider` persistita, e i due sono
                         assi indipendenti.
      --permission-mode <mode>
                         Esegui con <mode> invece della modalità nel file di
                         configurazione. Accetta anche --permission-mode=<mode>. Precedenza
                         massima: prevale su $CANDY_CODE_PERMISSION_MODE e
                         sulla chiave di configurazione permissionMode. Una di: default,
                         accept-edits, plan, auto, dont-ask,
                         bypass-permissions. Con nessuna impostata, la TUI e -p
                         partono in default (chiede prima di scritture e comandi
                         shell); solo un daemon avviato localmente parte in
                         bypass-permissions.
      --max-cost <usd>   Limita questa esecuzione a <usd> dollari USA di spesa
                         riportata: il turno che supererebbe il limite viene
                         rifiutato e non inviato. Accetta anche --max-cost=<usd>.
                         Precedenza massima: prevale su $CANDY_CODE_MAX_COST e
                         sulla chiave di configurazione maxCostUsd. Decimali ammessi, un
                         $ iniziale è accettato ($2.50); zero e negativi sono
                         rifiutati anziché letti come "nessun limite". /budget
                         alza o rimuove il limite per la sessione in esecuzione.
      --max-turns <n>    Limita questa esecuzione a <n> passi del ciclo di strumenti: il turno
                         che li esaurisce si ferma dove è e lo comunica.
                         Accetta anche --max-turns=<n>. Precedenza massima:
                         prevale sulla chiave di impostazione maxToolSteps (questo asse
                         non ha variabile d'ambiente). Un intero positivo;
                         zero viene rifiutato anziché letto come "nessun
                         limite", e un valore inutilizzabile rifiuta l'esecuzione
                         anziché rimettersi silenziosamente all'impostazione.
      --json-schema <path-or-json>
                         Vincola la risposta a un JSON Schema: un documento
                         {"type":"object",...} inline o un percorso a un file
                         che ne contiene uno. Accetta anche --json-schema=<value>;
                         la forma con = è quella da usare quando il percorso inizia
                         con "-". Solo i provider che dichiarano di supportare
                         risposte vincolate da schema eseguono la richiesta
                         — qualsiasi altro rifiuta con exit 2 anziché
                         fatturare una risposta non vincolata. Lo schema
                         regola la richiesta di auto-completamento del turno; i passi
                         che proseguono un ciclo di strumenti restano liberi (una
                         risposta JSON forzata non può contenere chiamate a strumenti).
      --append-system-prompt <text-or-@file>
                         Aggiungi regole dell'operatore al prompt di sistema di questa
                         singola esecuzione: testo inline, o @path a un file che le
                         contiene. Accetta anche --append-system-prompt=<value>;
                         la forma con = è quella da usare quando il percorso inizia
                         con "-". Le regole arrivano come un ulteriore blocco
                         fenced di istruzioni personali, mai un override: non
                         possono sostituire o degradare i livelli superiori, e
                         i marcatori di blocco contraffatti nel testo sono neutralizzati.
                         Limitato alle stesse dimensioni di un documento di istruzioni.
                         Solo con -p o il verbo run: un avvio senza
                         prompt a cui aggiungere rifiuta con exit 2 anziché
                         ignorare silenziosamente le regole fornite.
  -c, --continue         Riapre la sessione usata più di recente, transcript
                         e tutto il resto, invece di avviarne una nuova. Senza
                         ogni avvio apre una nuova sessione; Su in una
                         casella di input vuota richiama comunque i prompt precedenti.
      --resume [<id|name>]
                         Riapre una sessione salvata per id, prefisso id univoco o
                         nome (vedi `session list`). Senza valore, apre il
                         selettore di sessioni all'avvio; accanto a -p un target È
                         obbligatorio (il transcript alimenta l'one-shot e la
                         risposta viene salvata nella riga). Accetta anche
                         --resume=<id>. Non combinabile con --continue.
      --worktree [<name>]
                         Esegue l'intera sessione dentro un git worktree
                         main-<name> sul branch candy-code/<name>, creato
                         al primo uso; senza nome, il worktree ne riceve uno
                         scelto automaticamente. All'uscita un worktree senza
                         commit e senza modifiche viene rimosso; uno con
                         lavoro resta e ne annuncia il percorso. Rifiutato
                         fuori da un git work tree e accanto a `serve`.
      --incognito        Avvio che non conserva nulla: nessuna riga di sessione, nessun
                         transcript, nessuna scrittura automatica in memoria a fine turno.
                         Ciò che l'esecuzione ha prodotto vive solo nel processo;
                         sessioni e note salvate PRIMA restano leggibili.
                         Rifiutato accanto a --continue o --resume, che riaprono
                         sessioni conservate.
      --restricted       Avvio che non può eseguire codice: Bash, PtyRun, Task,
                         Workflow, ShellStop e mcp_call vengono rimossi da
                         ogni set rivolto al modello per l'intera sessione, e
                         /permissions non può ripristinarli. I tool file restano,
                         sotto il vincolo di percorso esistente. Accetta anche
                         --restricted=true|false, così un wrapper può scavalcare
                         un alias che porta il flag nudo. Sopravvive al rilancio.
      --safe-mode        Avvio che ignora ogni fiducia: ogni radice di
                         progetto fidata risponde come non fidata (hooks, MCP
                         di progetto e shell di comando), nessun bundle si carica, e nessuna
                         skill, comando o agente esterno viene scoperto.
                         Impostazioni, skill e comandi nativi restano. Accetta anche
                         --safe-mode=true|false per scavalcare un
                         alias. Sopravvive al rilancio.
  -h, --help             Mostra questo messaggio di aiuto
  -v, --version          Mostra la versione installata ed esce
      --                 Fine delle opzioni: ogni argomento successivo è posizionale,
                         mai un flag

Variabili d'ambiente:
   CANDY_CODE_PROVIDER    Provider da usare: openai, azure, anthropic, claude-code,
                          codex, sglang, bedrock, vertex, gemini,
                          openrouter, custom
   CANDY_CODE_MODEL       Nome del modello (scavalca il default del provider; --model vince)
   CANDY_CODE_PERMISSION_MODE
                          Modalità di permesso di avvio, scavalca la
                          chiave di config permissionMode (--permission-mode vince)
   CANDY_CODE_BACKEND_CMD Comando shell per un adattatore backend custom, sotto il
                          contratto PROSE: riceve la cronologia JSON su stdin, scrive
                          il testo della risposta su stdout, usato verbatim
                          (tagliato solo alle due estremità, quindi ogni newline, riga
                          vuota e indentazione interna sopravvive).
   CANDY_CODE_BACKEND_CMD_STREAM
                          Stesso shell-out sotto l'altro contratto, uno STREAM di TOKEN
                          : un token per riga, il newline tra due
                          token è incorniciatura e viene scartato, e una riga VUOTA è
                          un newline letterale nella risposta. Il callback scatta per
                          token man mano che il comando li produce, ma il ciclo di lettura
                          è sincrono, quindi lo schermo si ridisegna una volta alla fine
                          anziché token per token. Non intercambiabile con
                          CANDY_CODE_BACKEND_CMD in nessuna direzione — un wrapper
                          prose eseguito tramite questa variabile torna con ogni
                          newline eliminato e ogni riga vuota ridotta a una.
                          CANDY_CODE_BACKEND_CMD prevale quando entrambi sono impostati.
                          Per entrambi, non impostato, vuoto e solo-whitespace contano tutti
                          come assenti.
   CANDY_CODE_DISABLE_PARALLEL_TOOL_CALLS
                          Esegue le chiamate tool di un turno rigorosamente una alla volta.
                          Il dispatch concorrente è il default e raggruppa solo
                          tool non mutanti; questa è la via di fuga.
                          Persistilo come "parallelToolCalls": false in
                          ~/.candy-code/config.json.
   CANDY_CODE_PARALLEL_TOOL_DEADLINE
                          Secondi che un gruppo concorrente può eseguire prima che i
                          ritardatari vengano uccisi e segnalati come chiamate fallite
                          (default 90, deve essere 1-119; una frazione viene troncata).
                          Persistilo come "parallelToolDeadlineSeconds".
                          Precedenza: questa variabile, poi la chiave persistita,
                          quindi il default. Un valore fuori dall'intervallo 1-119, oppure uno che
                          non è affatto un numero, non conta come impostato — ricade
                          sulla fonte successiva anziché
                          scartarlo.
   CANDY_CODE_ADVISOR_MODEL
                          Il modello che lo strumento `Advisor` consulta per un secondo
                          parere: un completamento senza strumenti, fatturato come
                          qualsiasi altra chiamata. A differenza di CANDY_CODE_TITLE_MODEL,
                          non esiste un fallback economico — non impostato significa che lo
                          strumento non viene offerto. Letto all'avvio.
   CANDY_CODE_TITLE_MODEL Il modello economico usato per nominare automaticamente una sessione dopo
                          il primo scambio; il default è quello del provider.
   CANDY_CODE_SUMMARY_MODEL
                          Il modello che scrive i riepiloghi di compattazione;
                          il default è quello della conversazione stessa, che riutilizza
                          la cache dei prompt.
   CANDY_CODE_CONTEXT_PRUNING
                          auto, manual o off: come una sessione pota il proprio
                          contesto quando /pruning non ha scelto (default auto).
   CANDY_CODE_MAX_COST    Un tetto di spesa per questo avvio, in dollari USA
                          (decimali ammessi; un "$" iniziale è accettato;
                          --max-cost prevale). Un turno che supera il tetto
                          viene rifiutato.
   CANDY_CODE_CONNECT_TIMEOUT
                          Limite della fase di connessione, in secondi (decimali
                          ammessi; default 15.0), per i transport HTTP del
                          provider. Delimita solo l'instaurazione della connessione
                          — non è un timeout totale della richiesta. Per quanto
                          un server streaming connesso può impiegare a inviare
                          le intestazioni di risposta è l'impostazione separata
                          streamHeaderTimeoutSeconds.
   CANDY_CODE_SEARCH_ENDPOINT
                          API di ricerca interrogata dallo strumento WebSearch integrato.
   CANDY_CODE_SESSION_RETENTION_DAYS
                          Un numero intero positivo di giorni: ogni avvio elimina
                          le sessioni non toccate da almeno quel tempo.
   CANDY_CODE_SHARE_UPLOAD_URL
                          Host di upload ritirato: /share non carica mai
                          nulla. Se impostato, l'export locale viene comunque
                          scritto e la risposta rifiuta apertamente la chiave e indica
                          /share serve, che pubblica una pagina di snapshot
                          self-hosted sul proprio candy-code serve.
   CANDY_CODE_WORKTREES_DIR
                          Directory base sotto la quale vengono creati i git
                          worktree per teammate.
   CANDY_CODE_DISABLE_MOUSE
                          Qualsiasi valore diverso da vuoto o 0 disattiva il
                          tracciamento del mouse.
   CANDY_CODE_DISABLE_MOUSE_CLICKS
                          Qualsiasi valore diverso da vuoto o 0 ignora i gesti
                          di click mantenendo lo scroll della rotellina.
   CANDY_CODE_DISABLE_PROMPT_CACHE
                          Qualsiasi valore diverso da vuoto o 0 disattiva i
                          breakpoint della cache dei prompt del provider.
   CANDY_CODE_DISABLE_PROMPT_SUGGESTIONS
                          Qualsiasi valore diverso da vuoto o 0 disattiva il suggerimento
                          del messaggio successivo in grigio (→ lo accetta) dopo ogni turno.
   CANDY_CODE_DISABLE_AUTO_MEMORY
                          Qualsiasi valore diverso da vuoto o 0 disattiva l'auto-memory:
                          il salvataggio di fatti duraturi come note dopo un turno e
                          il passaggio dream che incorpora il journal di
                          compattazione in esse.
   CANDY_CODE_DISABLE_MODEL_METADATA
                          Qualsiasi valore diverso da vuoto o 0 disattiva la lettura e
                          l'aggiornamento del database dei modelli LiteLLM che dimensiona e
                          prezza i modelli privi di un valore integrato.
   CANDY_CODE_NO_UPDATE_CHECK
                          Qualsiasi valore diverso da vuoto o 0 disattiva il controllo
                          giornaliero delle release phar e l'avviso di aggiornamento all'avvio;
                          nessuna richiesta lascia il processo e un avviso
                          in cache obsoleto non viene più mostrato.
   CANDY_CODE_DISABLE_SYMBOL_MAP
                          Qualsiasi valore diverso da vuoto o 0 esclude la mappa dei
                          simboli ordinata dal prompt di sistema.
   CANDY_CODE_BACKGROUND  light o dark — forza ciò che il tema adattivo
                          ritiene del background del terminale, saltando
                          il probe OSC 11 e COLORFGBG.
   CANDY_CODE_DEBUG_SKILLS
                          Qualsiasi valore diverso da vuoto o 0 rimette le righe di SkillLoader
                          per ogni skip e per ogni directory rifiutata su
                          stderr.
   CANDY_CODE_DEBUG_COMMANDS
                          Qualsiasi valore diverso da vuoto o 0 rimette le righe di CommandLoader
                          di rifiuto della scoperta su stderr.
   CANDY_CODE_DEBUG_RULES Qualsiasi valore diverso da vuoto o 0 rimette le righe di RuleLoader
                          di rifiuto della scoperta su stderr.
   CANDY_CODE_DEBUG_STREAM
                          Qualsiasi valore diverso da vuoto o 0 mantiene su stderr la riga
                          "onToken observer threw" di Chat. Il
                          distacco avviene comunque in entrambi i casi.
   CANDY_CODE_SERVER_HOST L'indirizzo a cui `serve` si associa (--host ha la precedenza).
   CANDY_CODE_SERVER_PORT La porta a cui `serve` si associa (--port ha la precedenza).
   CANDY_CODE_SERVER_ALLOWED_ORIGINS
                          Origini aggiuntive separate da virgola che `serve` accetta
                          (--allowed-origin ha la precedenza).
   CANDY_CODE_SERVER_ALLOWED_HOSTS
                          Nomi host aggiuntivi separati da virgola a cui `serve` risponde
                          (--allowed-host ha la precedenza).
   CANDY_CODE_SERVER_ALLOWED_IPS
                          IP client o CIDR separati da virgola che `serve` ammette
                          oltre al loopback (--allowed-ips ha la precedenza).
   CANDY_CODE_SERVER_WEB_ROOT
                          Directory da cui `serve` eroga la web UI (--web-root
                          ha la precedenza).
   CANDY_CODE_SERVER_TOKEN
                          Il token richiesto da `serve`, in alternativa a quello
                          nella directory di stato (almeno 32 caratteri; per
                          i container).
   CANDY_CODE_SERVER_DIR  La directory in cui `serve` conserva token, lock,
                          record di discovery e log (predefinita
                          ~/.candy-code/server; creata con permessi 0700).
   CANDY_CODE_SERVER_PARENT_PID
                          Un processo che `serve` arresta insieme a sé (--parent-pid ha la precedenza).
   CANDY_CODE_MCP_DISABLE
                          1, true o yes (senza distinzione maiuscole) disattiva
                          MCP del progetto: .mcp.json viene trattato come assente, nessun
                          server viene avviato. Non impostato, 0 o qualsiasi altro valore mantiene
                          MCP attivo — a differenza delle variabili in stile flag,
                          solo queste tre parole hanno effetto.
   CANDY_CODE_QUIET_LOGS  1, true o yes (senza distinzione maiuscole) silenzia
                          il canale laterale error_log() a livello di processo nel suo unico
                          sink; non impostato, 0 o qualsiasi altro valore mantiene
                          i diagnostici attivi. Solo all'avvio, nessuna chiave di configurazione.
   CANDY_CODE_REDUCED_MOTION
                          1, true o yes (senza distinzione maiuscole) blocca lo
                          spinner dell'agente su un singolo frame statico — per utenti
                          sensibili al movimento o con preferenza di movimento ridotto. Letto una sola volta all'avvio;
                          non esiste una chiave di configurazione.
   CANDY_CODE_SD_BASE_URL URL di base del server Stable Diffusion in stile A1111 (sdapi)
                          a cui il media transport si connette.
                          Precedenza: un override esplicito nel codice, poi questa
                          variabile, poi l'impostazione sd.baseUrl.
   CANDY_CODE_MEDIA_RENDER_MODE
                          Come le immagini generate vengono renderizzate nel terminale
                          (il livello env dell'impostazione ui.imageRenderMode; vedi
                          docs/ENVIRONMENT.md per i valori accettati).
   CANDY_CODE_ALLOW_ROOT_TESTS
                          Impostare esattamente a 1 per consentire alla TEST SUITE di candy-code
                          di eseguire come root; non impostato o qualsiasi altro valore, la suite
                          rifiuta di avviarsi con euid 0. Nulla riguardo a un
                          avvio di candy-code cambia — la suite non è una
                          interfaccia per l'utente.
   CANDY_CODE_TOOL_INPUT  L'intera mappa degli argomenti della chiamata corrente a uno script
                          tool, codificata in JSON, esportata nel processo
                          figlio di ogni esecuzione di un tool in ~/.candy-code/tools
                          ; l'applicazione la scrive, non la rilegge mai, e
                          nessuno la imposta manualmente.
   CANDY_CODE_OTEL_BATCH_SIZE
                          Numero di span che un batch di esportazione OTLP trasporta
                          (predefinito 64, limitato a 1..2048).
   CANDY_CODE_OTEL_TIMEOUT
                          Secondi massimi per ogni tentativo di esportazione OTLP
                          (predefinito 3; un valore non positivo o malformato
                          ricade sul valore predefinito).

   docs/ENVIRONMENT.md elenca ogni variabile che questa build legge, con il suo
   contratto completo.

Codici di uscita (modalità one-shot e ogni sottocomando):
  0                      Il prompt è stato eseguito e ha prodotto una risposta, oppure il
                         sottocomando ha risposto
  1                      Eseguito e fallito: il backend ha generato un errore (host irraggiungibile,
                         chiave rifiutata, errore del modello) — un nuovo tentativo può aiutare — oppure un
                         sottocomando è stato eseguito ed è fallito (un controllo doctor ha restituito
                         FAIL, un verbo `session` non ha trovato la sessione, un
                         .mcp.json fidato non ha potuto essere analizzato)
  2                      Errore di utilizzo o configurazione, nulla è stato tentato
                         e un nuovo tentativo non aiuterà: nessun prompt fornito, un
                         flag non riconosciuto, un argomento nudo che non indica
                         una directory esistente (un prompt richiede -p), un --root
                         che non indica alcuna directory, un file composer
                         autoload.php mancante, oppure un provider selezionato
                         che non può essere istanziato — tramite
                         $CANDY_CODE_PROVIDER o il provider persistito in
                         ~/.candy-code/config.json tramite Ctrl+P "Switch model".
                         Un'esecuzione one-shot non ricade mai sul provider echo offline
                         quando un provider è stato selezionato esplicitamente.
                         Un sottocomando a cui è stato fornito un operando mancante o sconosciuto
                         (`session`, `mcp bogus`, `completion tcsh`) segnala
                         anche qui.
  130/143/129             TUI: un segnale ha interrotto il loop — 128+N per
                         SIGINT (Ctrl+C), SIGTERM, SIGHUP; un'uscita
                         cooperativa (/exit, q) esce comunque con 0.

Esempi:
  candy-code -p "Spiega la differenza tra require e include"
  CANDY_CODE_PROVIDER=anthropic CANDY_CODE_MODEL=claude-sonnet-4-20250514 \
    candy-code -p "Scrivi un hello world in Go"
  candy-code run "Scrivi un hello world in Go"
  candy-code doctor
  candy-code models --output-format json | jq '.result.providers'
  eval "$(candy-code completion bash)"
  candy-code serve --port 7420

Per ulteriori informazioni, consulta il README:
  https://github.com/detain/sugarcraft/tree/master/candy-code

