    'cli.references.redundant' => 'la voce `references` {path} si trova dentro il workspace della sessione — il jail la copre già, quindi non viene aggiunta come seconda root di lettura.',
    'cli.references.unusable' => 'una voce `references` non è stata letta — deve essere un oggetto con un `path` (o una stringa di percorso semplice); questa voce è stata saltata.',
    'cli.refuse.bad_mode' => '{source} è \'{value}\', che non è una modalità di permesso (atteso uno di: {valid}). Rifiuto di avviare piuttosto che ripiegare sul default permissivo.',
