    'cli.refuse.config_bom' => 'inizia con un byte-order mark UTF-8, che JSON non consente — salva di nuovo il file come UTF-8 senza BOM',
    'cli.refuse.config_dangling' => '{path} esiste ma non è un file leggibile (è un symlink che non si risolve in uno). Rifiuto di avviare piuttosto che eseguire con una policy di permesso sconosciuta.',
    'cli.refuse.config_is_directory' => '{path} esiste ma non è un file leggibile (è una directory). Rifiuto di avviare piuttosto che eseguire con una policy di permesso sconosciuta.',
    'cli.refuse.config_not_json' => '{path} non è JSON utilizzabile ({error}). Rifiuto di avviare piuttosto che eseguire con una policy di permesso sconosciuta.',
    'cli.refuse.config_not_object' => 'il livello superiore non è un oggetto JSON',
    'cli.refuse.config_unreachable' => '{path} non è raggiungibile: {reason}, quindi non è possibile sapere se vi sia configurata una policy di permessi. Avvio rifiutato per non eseguire con una policy di permessi sconosciuta.',
    'cli.refuse.config_unreadable' => '{path} esiste ma non è stato possibile leggerlo (verificarne i permessi). Avvio rifiutato per non eseguire con una policy di permessi sconosciuta.',
    'cli.refuse.dangling_directory' => '{dir} è un symlink che non si risolve in una directory che questo processo può cercare',
    'cli.refuse.foreign_owner' => '{path} appartiene a uid {uid}, non all\'account con cui questa sessione è in esecuzione, quindi la policy di permessi e la catena di hook che trasporta sono di qualcun altro. Avvio rifiutato per non eseguire la policy di un altro account.',
    'cli.refuse.hook_chain' => '{error} Avvio rifiutato per non eseguire con una catena di hook diversa da quella configurata.',
    'cli.refuse.hooks_unreachable' => '{path} non è raggiungibile: {reason}, quindi non è possibile sapere se vi siano configurati hook. Avvio rifiutato per non eseguire con una catena di hook sconosciuta.',
    'cli.refuse.keybindings' => 'l\'impostazione keybindings non è utilizzabile: {reason}. Rimuovere la chiave per eseguire con i binding predefiniti (il riferimento /keys li elenca). Avvio rifiutato per non eseguire con sostituzioni di tasti non richieste.',
    'cli.refuse.max_cost_env' => '$CANDY_CODE_MAX_COST è \'{value}\', che non è un limite di spesa. Atteso un numero positivo di dollari USA (decimali ammessi, un $ iniziale accettato), ad esempio 5 o $2.50. Zero e negativi sono rifiutati anziché interpretati come "nessun limite" perché sono la richiesta opposta; un valore troppo grande per essere rappresentato (1e309, cioè infinito) è rifiutato perché imporrebbe un limite che non scatta mai. Annullare la variabile per nessun limite. Avvio rifiutato per non eseguire senza tetto con un limite richiesto.',
    'cli.refuse.max_cost_flag' => '--max-cost è \'{value}\', che non è un limite di spesa. Atteso un numero positivo di dollari USA (decimali ammessi, un $ iniziale accettato), ad esempio 5 o $2.50. Zero e negativi sono rifiutati anziché interpretati come "nessun limite" perché sono la richiesta opposta; un valore troppo grande per essere rappresentato (1e309, cioè infinito) è rifiutato perché imporrebbe un limite che non scatta mai. Rimuovere il flag per nessun limite. Avvio rifiutato per non eseguire senza tetto con un limite richiesto.',
    'cli.refuse.max_cost_setting' => 'maxCostUsd nelle impostazioni è {value}, che non è un limite di spesa. Atteso un numero positivo di dollari USA, ad esempio 5 o 2.5. Rimuovere la chiave per nessun limite. Avvio rifiutato per non eseguire senza tetto con un limite richiesto.',
    'cli.refuse.max_turns_flag' => '--max-turns è \'{value}\', che non è un limite di passi. Atteso un numero intero positivo di passi del ciclo di strumenti, ad esempio 8. Zero è rifiutato anziché interpretato come "nessun limite" perché è la richiesta opposta; un valore troppo grande per essere rappresentato è rifiutato perché imporrebbe un limite che non scatta mai. Rimuovere il flag per rimandare all\'impostazione maxToolSteps. Avvio rifiutato per non eseguire senza tetto con un limite richiesto.',
    'cli.refuse.no_home' => 'questo processo non può determinare quale directory home sia la tua ($HOME non impostata, $USERPROFILE non impostata e nessuna voce passwd per il suo uid), quindi la policy di permessi e la catena di hook in ~/.candy-code non possono essere individuate. Avvio rifiutato per non leggere una di esse da una directory di fallback scrivibile da tutti — esportare HOME all\'account a cui questa sessione appartiene.',
    'cli.refuse.no_project_root' => 'impossibile determinare una root di progetto — la directory di lavoro del processo non è disponibile (eliminata o illeggibile). Passare --root <dir>.',
    'cli.refuse.not_searchable' => '{dir} non è cercabile da questo processo',
    'cli.refuse.project_settings_unusable' => '{path} non è stato possibile leggerlo per le sue permissionRules ({reason}). Avvio rifiutato per non eseguire con una policy di permessi sconosciuta.',
    'cli.refuse.world_writable' => '{path} è scrivibile da ogni account su questa macchina, quindi la policy di permessi e la catena di hook che trasporta non sono di questo utente. Avvio rifiutato per non eseguire una policy che chiunque potrebbe aver scritto — `chmod o-w {path}`.',
