    'cli.selfupdate.composer_mode_root' => 'candy-code: self-update sostituisce un\'installazione phar, e questa copia è il pacchetto sugarcraft/candy-code installato come root Composer — non c\'è un phar da sostituire, e un pacchetto root non può aggiornarsi tramite il proprio comando di dipendenza. Aggiornarlo con: {command} (il clone recupera il nuovo sorgente, poi ricostruisce l\'albero vendor).',
