    'cli.selfupdate.sig.deprecated' => 'candy-code: questa release firma i byte grezzi del phar con {asset}; quella procedura legacy legge l\'intero artefatto in memoria ed è accettata per un ulteriore ciclo di release. Pubblicare {replacement} — una firma Ed25519 sul corpo sidecar sha256 — così la verifica non lascia mai lo stream.',
    'cli.selfupdate.sig.sidecar_invalid' => 'candy-code: {asset} non verifica il sidecar {sidecar} del {phar} scaricato rispetto alla chiave di release fissata. Nulla è stato sostituito.',
    'cli.selfupdate.signature_invalid' => 'candy-code: {asset} non verifica il {phar} scaricato rispetto alla chiave di release fissata. Nulla è stato sostituito.',
