    'cli.selfupdate.staged_windows' => 'candy-code: l\'aggiornamento è in staging per il ballo di rilancio — {new} sostituisce {path} quando questo processo esce; l\'avanzamento è registrato in {path}.swap.log e la copia conservata resta in {old}.',
    'cli.selfupdate.swap_leftover' => 'candy-code: un precedente self-update ha lasciato uno swap in staging in {new} mai applicato (il suo swap log registra i tentativi abbandonati). Questa esecuzione sostituisce lo staging prima dell\'aggiornamento.',
    'cli.selfupdate.swap_spawn_failed' => 'candy-code: l\'helper di swap non è stato possibile avviarlo; i byte verificati restano in staging in {new} e la copia in esecuzione è intatta. Completare il rinomina su {path} a mano, oppure rieseguire self-update quando nulla trattiene il file.',
    'cli.selfupdate.uncomparable' => 'candy-code: questa installazione riporta {current}, che non è una versione di release che self-update possa ordinare.',
