    'cmd.mcp-auth.disable.done' => '✓ Disabilitato `{server}` per questa sessione — le chiamate sono rifiutate dal prossimo turno; il roster rivolto al modello non viene ri-derivato (legge della cache), quindi i suoi tool restano elencati fino al riavvio.',
