    'cmd.mcp-auth.disable.persist-added' => 'Persistito `{server}` nella lista disabledMcpServers dell\'utente; sarà rifiutato anche al lancio.',
    'cmd.mcp-auth.disable.persist-glob' => '! `{server}` contiene metacaratteri fnmatch; --persist scrive solo nomi esatti — un glob memorizzato potrebbe coprire server che questo comando non ha mai nominato.',
