    'cmd.mcp-auth.empty' => "Nessuna credenziale MCP memorizzata.\n\nLe credenziali servono solo per i server che richiedono il login OAuth; un\nserver http dichiarato che non ne richiede alcuna funziona solo con la sua \"url\".\nI server stessi sono dichiarati sotto \"mcpServers\" in\n<project>/.mcp.json — guida: docs/MCP.md, \"{section}\".",
    'cmd.mcp-auth.enable.done' => '✓ Abilitato `{server}` per questa sessione — i rifiuti di sessione vengono revocati dal turno successivo; le chiamate vengono instradate di nuovo solo dove il routing di avvio già consente il nome.',
