    'cmd.mcp-auth.enable.usage' => 'Uso: /mcp enable <server> [--persist]',
    'cmd.mcp-auth.failed' => '✗ Registrazione fallita: {error}',
    'cmd.mcp-auth.heading' => '**MCP Servers**',
    'cmd.mcp-auth.login-armed' => "↻ Login MCP avviato per `{server}` — in attesa del link del browser.\n\nIl processo figlio associa una porta loopback; completalo in un browser mentre la TUI resta reattiva. Il client MCP di questa sessione ha memorizzato il suo store all'avvio, quindi il token avrà effetto al PROSSIMO avvio; `/mcp list` mostra la credenziale una volta salvata.",
    'cmd.mcp-auth.login-busy' => '! Un login per `{server}` è già in esecuzione — completa o annulla prima quello (il suo URL e lo stato sono nella trascrizione sopra).',
    'cmd.mcp-auth.login-code-delivered' => '✓ Il callback è stato consegnato al login in attesa per `{server}` — il processo figlio completa lo scambio lì, e il suo risultato appare nella trascrizione.',
    'cmd.mcp-auth.login-code-refused' => '! Impossibile consegnare il callback di login MCP per `{server}`: {reason}',
    'cmd.mcp-auth.login-code-reason-dial' => "il listener del login in attesa non ha risposto",
    'cmd.mcp-auth.login-code-reason-host' => 'solo gli host loopback `127.0.0.1` e `localhost` sono accettati',
    'cmd.mcp-auth.login-code-reason-noslot' => 'nessun login per quel server è attualmente in attesa su questo host',
    'cmd.mcp-auth.login-code-reason-port' => 'la porta non corrisponde alla porta di callback annunciata dal login in attesa',
    'cmd.mcp-auth.login-code-reason-scheme' => 'l\'URL di callback deve usare lo schema `http` semplice a cui il listener di login si associa',
    'cmd.mcp-auth.login-code-reason-shape' => 'il formato è `/mcp login <server> --code <callback-url>` con esattamente un URL',
    'cmd.mcp-auth.login-done' => '✓ Login MCP per `{server}` completato (exit {code}). I token si allegano al PROSSIMO avvio — avvia una nuova sessione perché il grant accompagni le richieste; `/mcp list` aggiorna il pannello.',
    'cmd.mcp-auth.login-failed' => <<<'TXT'
✗ Login MCP per `{server}` terminato con {code} senza salvare i token.

Le ultime righe del processo figlio sono sopra; lo stesso flusso in una shell (`candy-code mcp auth login {server}`) stampa l'errore completo ed è il posto dove debuggare problemi di endpoint o porta.
TXT,
    'cmd.mcp-auth.login-failed-spawn' => "✗ Impossibile avviare il processo figlio di login MCP per `{server}`.\n\nEsegui direttamente la forma shell: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-guidance' => "Il login interattivo è un comando shell, non un turno di chat:\n\n  candy-code mcp auth login <server> [token-url] [authorize-url] [registration-url]\n\nEsegue il flusso OAuth authorization-code con PKCE: il tuo browser\nrestituisce il codice a un listener loopback nella shell, e i token salvati\nvengono allegati ai server http corrispondenti dal prossimo avvio.",
    'cmd.mcp-auth.login-no-entry' => "✗ Impossibile trovare il punto di ingresso di questo programma per fork `mcp auth login {server}`.\n\nEsegui direttamente la forma shell: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-served-armed' => "↻ Login MCP avviato per `{server}` sull'host SERVER — il suo link arriva sotto; aprilo in un browser sulla tua macchina. Il tuo browser non può raggiungere direttamente il listener loopback del server: quando atterra su una pagina di errore di connessione, copia l'indirizzo di quella pagina e invia `/mcp login {server} --code <that-url>` per consegnare il callback al login in attesa. I token si allegano al PROSSIMO avvio; `/mcp list` mostra la credenziale una volta salvata.",
    'cmd.mcp-auth.login-url' => '→ Apri questo URL per autorizzare `{server}`:\n\n  {url}',
    'cmd.mcp-auth.not-found' => '! Nessuna credenziale trovata per `{server}`.',
    'cmd.mcp-auth.registered' => <<<'TXT'
✓ `{server}` registrato con successo
Client ID: `{client}`
Le richieste a un server MCP http con questo URL esatto ora portano questo token automaticamente, aggiornato prima della scadenza; i server avviati prima di questo comando lo acquisiscono al prossimo avvio.
TXT,
    'cmd.mcp-auth.remove-usage' => 'Uso: mcp auth remove <server>',
    'cmd.mcp-auth.reconnect.auth' => '! `{server}` ora riporta che richiede un login OAuth.',
    'cmd.mcp-auth.reconnect.denied' => '! `{server}` è rifiutato da un pattern di negazione.',
    'cmd.mcp-auth.reconnect.drifted' => "Config MCP cambiata dall'avvio — riconnessione rifiutata. Una riconnessione riavvia i server esattamente come `.mcp.json` li contiene ora, mentre questa sessione è stata ammessa contro i byte fidati all'avvio; avviare voci divergenti eseguirebbe server che le decisioni di ammissione non hanno mai visto. Riavvia la sessione per applicare la modifica; è l'unico percorso di applicazione.",
    'cmd.mcp-auth.reconnect.error' => 'Avvio fallito: {error}',
    'cmd.mcp-auth.reconnect.heading' => '**Reconnected MCP servers**',
    'cmd.mcp-auth.reconnect.no-client' => 'Nessun client MCP in questa sessione — nulla da riconnettere (nessun `.mcp.json` è stato fidato all\'avvio).',
