    'cmd.mcp-auth.reconnect.state.up' => 'su',
    'cmd.mcp-auth.reconnect.tool-drift' => 'offre {now} strumenti; questa sessione è stata costruita con {was} — il roster rivolto al modello non viene ri-derivato a metà sessione, avvia una nuova sessione per adottarli',
    'cmd.mcp-auth.reconnect.unknown' => 'Questa sessione non ha registrato alcun digest di avvio per `.mcp.json`, quindi una riconnessione non può provare che la config contenga ancora i byte da cui l\'avvio è partito — rifiutato, il riavvio è l\'unico percorso di applicazione.',
    'cmd.mcp-auth.removed' => '✓ Credenziali rimosse per `{server}`',
