    'cmd.mcp-auth.status.expiring' => '● in scadenza',
    'cmd.mcp-auth.status.none' => '○ nessuna credenziale',
    'cmd.mcp-auth.undiscovered' => "! Gli endpoint OAuth non sono stati scoperti per `{server}`.\n\nForniscili esplicitamente:\n  `mcp auth add {server}` *<registration-url>* *<token-url>*\n\nNiente da scoprire di solito significa niente da registrare: un\nserver che non richiede login funziona solo con la sua \"url\" una volta\ndichiarato in .mcp.json (docs/MCP.md, \"{section}\").",
    'cmd.mcp-auth.unknown' => 'Sottocomando sconosciuto \'{sub}\'. Usa: list, add, remove, login, reconnect, enable, disable',
    'cmd.mcp-auth.usage' => "Uso:\n  mcp auth list                    — elenca i server registrati\n  mcp auth add <server> [reg-url] [token-url]  — salva le credenziali OAuth per un server\n  mcp auth remove <server>         — rimuovi le credenziali di un server\n  mcp auth login <server>          — stampa il comando shell per il login interattivo\n  /mcp reconnect                   — riavvia i server dichiarati, solo se .mcp.json corrisponde ancora all'avvio\n  /mcp enable <server> [--persist]   — solleva il rifiuto di questa sessione per un server dichiarato\n  /mcp disable <server> [--persist]  — rifiuta le chiamate di un server dichiarato per questa sessione",
