    'sandbox.hook.not_run' => 'Non eseguito: l\'hook `{hook}` è incluso nella sandbox `{mode}` tramite sandboxScope, ma la sandbox {name} non può avviarsi su questo host ({reason}). Nulla è stato eseguito, in sandbox o meno. Informa l\'utente: può correggere {name} ({remedy}) o impostare bashSandbox a "off".',
    'sandbox.lsp.not_started' => 'Non avviato: il server linguistico `{language}` ({command}) è incluso nella sandbox `{mode}` tramite sandboxScope, ma la sandbox {name} non può avviarsi su questo host ({reason}). Nulla è stato avviato, in jail o meno. Informa l\'utente: può correggere {name} ({remedy}), impostare bashSandbox a "off", oppure esentare questo server con `"sandbox": false` nella sua voce `lsp`.',
    'sandbox.mcp.not_started' => 'Non avviato: il server MCP `{server}` è incluso nella sandbox `{mode}` tramite sandboxScope, ma la sandbox {name} non può avviarsi su questo host ({reason}). Nulla è stato avviato, in jail o meno. Informa l\'utente: può correggere {name} ({remedy}), impostare bashSandbox a "off", oppure esentarlo con `"sandbox": false` nella sua voce di livello utente.',
    'sandbox.mcp.opt_out_ignored' => 'Ignorato: l\'opt-out `"sandbox": false` sul/i server MCP {servers} non proviene dal file di impostazioni utente — solo il livello utente può esentare un server stdio dalla jail sandboxScope. Il/i server restano in jail come previsto.',
    'sandbox.runner.skipped' => 'Saltato: l\'esecuzione {scope} è inclusa nella sandbox `{mode}` tramite sandboxScope, ma la sandbox {name} non può avviarsi su questo host ({reason}). Nulla è stato eseguito, in sandbox o meno. Informa l\'utente: può correggere {name} ({remedy}) o impostare bashSandbox a "off".',
    // ── C-AGT-4.e: cross-session mail (`SendMessage` `to: "session:<id>"`,
    // SessionMailbox drains). Own region for this step; other locales arrive
    // with the i18n carry wave.
    'send.session.sent' => 'In coda per la sessione {target}: leggerà il messaggio quando sarà inattiva (il suo agente lo ha inviato come {id}). Attende come istruzione di follow-up, non come messaggio dell\'utente.',
    'send.session.subagent' => 'Un sub-agente non può inviare messaggi a un\'altra sessione; i target `session:` sono riservati all\'agente della sessione stessa — invia un messaggio al tuo genitore, oppure segnala e lascia che il genitore parli per la conversazione.',
    'send.session.self' => 'Questa è la sessione corrente; stai già parlando qui.',
    'send.session.target_invalid' => '"session:{target}" non è un id di sessione: può contenere solo lettere, cifre, punto, underscore e trattino.',
    'send.session.unknown' => 'Nessuna sessione archiviata {target} — candy-code non la trova, quindi non ha nulla da recapitare.',
    'send.session.background' => 'La sessione {target} è un daemon in background; un daemon /bg non ha una casella di ricezione da svuotare.',
    'send.session.foreign_root' => 'La sessione {target} appartiene a una root di progetto diversa, quindi questa sessione non può inviarle messaggi.',
