    'chat.clipboard.clipped' => 'Copia negli appunti limitata a {max} su {chars} caratteri.',
    'chat.clipboard.no_image' => 'Nessuna immagine negli appunti da allegare. Ctrl+V legge un\'immagine tramite pngpaste (macOS), wl-paste (Wayland) o xclip (X11); incolla testo con il tasto di incolla del terminale, oppure allega un file con @path.',
    'chat.command.error' => '**Error:** {error}',
    'chat.compact.idle_advisory' => 'Questa sessione è inattiva da oltre un\'ora e ha raggiunto ~{tokens} token stimati, oltre la finestra di contesto di {limit} token. Esegui /compact per ridurre il contesto prima di continuare. Inviare un altro messaggio non lo invierà così com\'è: il turno successivo supera la soglia di compattazione automatica, quindi gli scambi più vecchi vengono riassunti per primi, e il turno viene rifiutato del tutto se ciò non libera spazio sufficiente.',
    'chat.compact.idle_auto_scheduled' => 'Compattazione automatica inattiva: la sessione ha superato la finestra di inattività con la trascrizione oltre la soglia di compattazione (~{tokens} token stimati su una finestra di {limit} token), quindi la richiesta di riepilogo è stata inviata senza intervento. Il ripiegamento si applica al turno successivo; nulla viene fatturato due volte e nessuna risposta viene inviata a nessuno.',
    'chat.compact.idle_folded' => 'Compattato durante l\'inattività: da ~{before} token stimati a ~{after}. `compaction.idleAuto` ha eseguito la soglia automatica mentre la sessione era inattiva, quindi gli scambi condensati sono ora riepiloghi.',
    'chat.copy.bad_arg' => 'Uso: /copy [n] — n è un numero intero che conta i blocchi di codice delimitati dalla fine dell\'ultima risposta; "{arg}" non lo è.',
