    'chat.goal.none_set' => 'Nessun obiettivo impostato. `{command} <condition>` ne imposta uno: l\'agente ci lavora subito, e dopo ogni turno il modello di titolo verifica la trascrizione per prove del raggiungimento, rimandando l\'agente al lavoro finché non è raggiunto (fino a {rounds} turni di follow-up).',
