    'chat.title.error' => '**Errore:** {error}',
    'chat.turn.loop_guard' => 'Questo turno è stato interrotto dalla guardia anti-loop di chiamate ripetute: il modello ha chiamato {tool} {count} volte con gli stessi argomenti ottenendo sempre lo stesso risultato. La risposta sopra descrive dove si è fermato. Indicalo verso un approccio diverso, oppure digita `continue` quando qualcosa è cambiato.',
    'chat.turn.output_limit' => 'Il provider ha interrotto questa risposta al limite di output, quindi il testo sopra potrebbe terminare a metà pensiero. Aumenta `maxOutputTokens` in ~/.candy-code/config.json per una risposta singola più lunga, oppure chiedi il resto nel prossimo messaggio.',
    'chat.turn.steps_exhausted' => 'Questo turno ha esaurito tutti i suoi step di tool prima che il lavoro fosse completato, quindi la risposta sopra descrive dove si è fermato — cosa è finito e cosa resta — non una risposta conclusa. Digita `continue` per riprendere da lì, oppure alza il limite per turni agentici più lunghi — il flag --max-turns all\'avvio prevale sull\'impostazione `maxToolSteps` in ~/.candy-code/config.json, quindi alza quella in vigore.',
    'chat.turn.unpriced_model' => 'Questa app non ha un prezzo registrato per il modello `{model}`, quindi questo turno è stato fatturato $0.00 come limite inferiore, non come chiamata gratuita — i totali di spesa e il tetto di spesa sono sottostimati finché non esiste una tariffa. Dichiarane una sotto `modelPrices` in ~/.candy-code/config.json (USD per 1M token, chiavi `input` e `output`) per prezzarlo.',
