    'host.agents.accept.bad_name' => '`{name}` non è un nome di bozza. Una bozza è un singolo file direttamente sotto la directory delle bozze, e ne passi il nome — lettere minuscole, cifre, punti, underscore e trattini — a /agents accept.',
    'host.agents.accept.exists' => 'Un preset chiamato {name} esiste già sotto {dir}/, e /agents accept non sovrascrive mai un preset attivo. Elimina o rinomina quel preset prima, oppure /agents new una bozza con un nome diverso.',
    'host.agents.accept.frontmatter' => 'La bozza {name} non ha un blocco di frontmatter che si analizzi in una mappa, quindi non è stata promossa. Esegui di nuovo /agents new, oppure correggi il file e accettala ancora.',
    'host.agents.accept.missing' => 'Nessuna bozza chiamata {name} sotto {dir}/. Esegui /agents new per crearne una, oppure /agents proposed per elencare le bozze.',
    'host.agents.accept.mode' => 'La bozza {name} dichiara `permissionMode: {mode}`, che non è una delle modalità di questa porta. Dichiara una di: {modes} — oppure ometti la chiave per `default`.',
    'host.agents.accept.moved' => 'La bozza {name} è ora {path} — il roster della prossima sessione la carica come preset di progetto.',
