    'host.agents.accept.type' => 'La bozza {name} dichiara `{key}` come un valore che il lettore di preset non può tipizzare — vuole una stringa o una lista di stringhe.',
    'host.agents.accept.unknown' => 'La bozza {name} dichiara `{key}`, una chiave su cui nessun lettore di preset agisce{hint}. Rimuovila o correggi l\'ortografia; /agents accept promuove solo file le cui chiavi questa porta legge.',
    'host.agents.error' => 'Il comando /agents draft è fallito: {error}',
    'host.agents.new.dispatched' => 'Si chiede all\'agente di redigere un preset da questa conversazione; scrive solo nel livello bozza, e nulla viene promosso finché non esegui /agents accept.',
    'host.agents.proposed.heading' => 'Bozze di agenti proposte:',
    'host.agents.proposed.none' => 'Nessuna bozza in attesa sotto {dir}/. Esegui /agents new per far redigere all\'agente una bozza da questa conversazione.',
    'host.agents.usage' => 'Uso: /agents [list|<name>|use <preset|default>|new <focus>|proposed|accept <name>]',
    'host.agents.not_configured' => 'Gestore agenti non configurato — nessun runtime di sub-agente è collegato a questo avvio, quindi /agents non può avviare o monitorare agenti. Un avvio `candy-code` semplice ne ha sempre uno; una build di integrazione host deve collegarlo.',
    // C-AGT-4.b: the `use` verb. Soft-appended after the block's last row;
