    'host.agents.use_switched' => '{name} è ora l\'agente primario di questa sessione — i suoi tool, modello e livello minimo di permessi restano attivi finché non torni indietro; un riavvio esegue il default della sessione semplice.',
    'host.agents.use_turn_running' => 'Un turno è in esecuzione — l\'agente primario cambia tra i turni, come un cambio di modalità di permesso.',
