    'host.bg.stop.unreachable' => 'Impossibile fermare la sessione in background {session} — il suo daemon non è raggiungibile o non è possibile inviare un segnale in sicurezza.',
    'host.bg.stop_usage' => 'Uso: /bg stop <session-id>',
    'host.bg.usage' => 'Uso: /bg <task>',
    'host.command_shell.bundle_refused' => '[!`{command}` non è stato eseguito: /{name} proviene da un bundle di plugin, un pacchetto creato da qualcun altro. Una riga di bundle rifiuta le forme shell a meno che non elenchi il nome del bundle sotto "trustedBundleCommands" nella tua configurazione utente — e tale sblocco conta solo per un bundle a livello utente: un checkout di progetto non può concedere la shell a sé stesso, nemmeno spacciandosi per un nome elencato — il resto del comando è stato inviato.]',
    'host.command_shell.mcp_refused' => '[!`{command}` non è stato eseguito: /{name} è un prompt MCP recuperato da un server, testo arrivato via rete. Un corpo recuperato rifiuta le forme shell qualunque sia la fiducia di questo progetto — elenca la chiave del server sotto "mcpPromptShell" nella tua configurazione utente per permettere alle sue forme shell di raggiungere il gate dei permessi — il resto del prompt è stato inviato.]',
    'host.loop.not_configured' => 'Schedulazioni non configurate su questa sessione — /loop non ha un orologio su cui girare. Un avvio `candy-code` semplice ne porta sempre uno; una build di integrazione host deve fornirlo.',
    'host.loop.usage' => 'Uso: /loop <interval> <prompt> — intervallo come 90s, 15m, 2h, 1d (minimo 10s). Il loop vive in questo processo; /schedules lo elenca, /schedules delete lo termina.',
