    'host.output_style.column_style' => 'Stile',
    'host.output_style.empty' => "Nessuno stile di output trovato.\nUno stile è un singolo file markdown in ~/.candy-code/styles/ (o .candy-code/styles/ nel progetto),\nnominato dal suo nome file: terse.md si seleziona con /output-style terse.",
    'host.output_style.footer' => "/output-style <name> seleziona uno stile; ne è attivo esattamente uno alla volta, e un\ncambio cancella il precedente. /output-style off libera lo slot. `off` è una\nparola riservata — un file chiamato off.md non può essere selezionato. Uno stile disabilitato dal suo\nproprio frontmatter (`enabled: false`) resta fuori dal prompt qualunque sia il suo nome.",
    'host.output_style.heading' => 'Stili di output (solo sessione — nulla qui viene scritto nella configurazione):',
