    'host.output_style.nothing_active' => 'Nessuno stile di output era attivo — nulla da cancellare.',
    'host.output_style.self_disabled' => "\nIl suo frontmatter dice enabled: false, quindi resta fuori dal prompt finché quella riga non cambia — la selezione non può sovrascrivere un file che si è disabilitato da solo.",
