    'host.schedules.not_configured' => 'Pianificazioni non configurate in questa sessione.',
    'host.schedules.usage' => 'Uso: /schedules [list] | add <name> <interval> <prompt> [--mode <mode>] [--provider <name>] [--heartbeat] | enable <name> | disable <name> | delete <name>. Le righe risiedono in ~/.candy-code/schedules.json; /schedules add ne crea una tramite i factory bounds dello Schedule tool, /loop ne registra una effimera.',
    'host.schedules.none' => 'Nessuna pianificazione. /schedules add <name> <interval> <prompt> ne crea una con gli stessi bounds dello Schedule tool, oppure scrivi una riga in ~/.candy-code/schedules.json (`name`, `every` in secondi, `prompt`, `root` — la directory di progetto in cui si attiva; opzionali `provider`, `permissionMode` (le grafie bypass-class vengono rifiutate; omettilo per il pavimento non interattivo), `enabled`, `timeoutSeconds`, `kind` (`task` risponde, `heartbeat` può restare silenzioso)), oppure /loop una per questa sessione. docs/SCHEDULES.md è il formato.',
