    'host.compact.safeguard.hold' => 'Compattazione rifiutata: il riepilogo del modello è stato scartato dall\'audit di salvaguardia ({detail}). Nulla è stato condensato e la cronologia completa è preservata — esegui /compact di nuovo per richiederlo al modello.',
    'host.compact.self_client_only' => '`/compact --self` chiede all\'agente di scrivere il proprio riepilogo — è la via interattiva TUI. Esegui `/compact` per piegare i riepiloghi scritti dal modello già presenti per questa sessione.',
