    'host.compact.summarising.other' => 'Riepilogo di {count} scambi precedenti con il modello — la trascrizione verrà compattata al loro arrivo.',
    'host.compact.thrash' => 'La compattazione del contesto è stata eseguita {times} volte di seguito e la trascrizione è tornata oltre il limite ogni volta, quindi questo prompt non è stato inviato e non è stata tentata ulteriore compattazione. Gli scambi recenti che la riscrittura mantiene integrali sono quelli che non entrano — riduci il più grande di essi (l\'output dei tool è di solito la parte più voluminosa), oppure riparti con /rewind o /clear. /model con una finestra di contesto più ampia risolve anche questo.',
    'host.compact.tier_report' => 'Il contesto ha raggiunto il livello di compattazione automatica, quindi gli scambi più vecchi sono stati riepilogati: {before} messaggi -> {after} messaggi, ~{saved}% dei token stimati liberati (~{tokens} token stimati ora, su una finestra di contesto di {limit} token).',
    'host.compact.truncated.one' => '{count} messaggio ha raggiunto {tier} da solo, quindi è stato troncato per entrare nella finestra di contesto anziché rifiutare il turno: ~{tokens} token stimati ora, su una finestra di contesto di {limit} token. Il testo inviato al modello porta un marcatore dove è stato tagliato; il tuo originale completo resta nella trascrizione, nascosto al modello.',
    'host.compact.truncated.other' => '{count} messaggi hanno raggiunto {tier} da soli, quindi sono stati troncati per entrare nella finestra di contesto anziché rifiutare il turno: ~{tokens} token stimati ora, su una finestra di contesto di {limit} token. Il testo inviato al modello porta un marcatore dove ciascuno è stato tagliato; i tuoi originali completi restano nella trascrizione, nascosti al modello.',
