    // --- fix-tui-interact 2026-10-14 ---
    'tui.picker.notice.slash_filter' => '`{word}` sembra un comando slash, non un filtro — Invio qui riprenderebbe la corrispondenza migliore. Premi Escape e digita il comando nell\'input.',
    'tui.app.stop_all_armed' => 'Per fermare tutti gli agenti in esecuzione — premi "s" di nuovo entro 3 s per confermare.',

    // --- fix-app-launch 2026-10-14 ---
    'appLaunch.doctor.mbstring_missing' => 'mancante — calcolo larghezza fotogrammi (mb_*) non eseguibile; reinstalla PHP con ext-mbstring',
    'appLaunch.doctor.intl_missing' => 'mancante — calcolo larghezza grapheme/IntlChar non eseguibile; reinstalla PHP con ext-intl',
    'appLaunch.notice.policy_changed' => '⚠ config.json o hooks.yaml modificati dall\'ultimo avvio. I nuovi hook di progetto restano in quarantena solo per questo avvio — verifica ~/.candy-code/config.json e hooks.yaml, poi verranno applicati',
    'appLaunch.notice.project_policy_changed' => '⚠ Il hooks.yaml di un progetto fidato contiene voci mai viste dall\'ultimo avvio. I nuovi hook di progetto restano in quarantena solo per questo avvio — verifica .candy-code/hooks.yaml del repository, poi verranno applicati',
    'appLaunch.notice.bypass_mode' => '⚠ Modalità permessi è bypass-permissions: ogni chiamata di tool viene eseguita senza conferma. Cambiala con /permissions (TUI), --permission-mode, o imposta una modalità permessi diversa in ~/.candy-code/config.json',
    // C-SEC-7.a: `-p` now defaults to the ASKING mode, so an unattended scripted
    // run that named no mode starts refusing — the launch says so once, and names
    // the one-flag fix. No trailing period — STDERR_LINE_FORMAT adds one
    // (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.headless_default' => 'ℹ -p avvia in modalità permessi default: un\'esecuzione non interattiva rifiuta ogni chiamata di tool che richiederebbe conferma. Passa --permission-mode (bypass-permissions esegue tutto) per esecuzioni scriptate',
    // C-SEC-7.e (owner ruling t212, option 3): the implicit autoReview default
    // announces once per session the first time it engages — de-duped by message
    // identity in the launch-notices store, like the bypass banner. Names the
    // opt-out and owns up to the money. No trailing period — STDERR_LINE_FORMAT
    // adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.auto_review_default' => '⚠ autoReview è attivo per default in questo avvio: le chiamate in auto-mode segnalate vengono revisionate dal modello titolo, e ogni revisione è una chiamata a modello a pagamento. Imposta autoReview a false in ~/.candy-code/config.json per disattivarlo',
    // C-SEC-6.b: names the file, what it added, and what could not be honoured.
    // No trailing period — STDERR_LINE_FORMAT adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.project_narrowing_rules' => '⚠ {file} ha ridotto i permessi di questo avvio: {count} regola/e deny/ask caricata/e per prima, {dropped} regola/e allow scartata/e — un file di progetto non può concedere allow',
    'appLaunch.notice.restricted' => '⚠ --restricted: questo avvio esegue senza tool di esecuzione codice — Bash, PtyRun, Task, Workflow, ShellStop e mcp_call sono assenti da ogni set esposto al modello; i tool file restano nel loro vincolo di percorso e /permissions non può ripristinare i tool rimossi',
    'appLaunch.notice.safe_mode' => '⚠ --safe-mode: root di progetto fidati, bundle, e skill, comandi e agenti esterni sono tutti ignorati per questo avvio — si comporta come se nulla fosse mai stato fidato',

    // --- fix-w2-chat 2026-10-14 ---
    'chat.launch.echo_backend' => 'Nessun provider configurato, quindi questa sessione usa il backend echo offline integrato — le risposte vengono ripetute localmente, nessun modello viene chiamato. Esegui `candy-code doctor` per vedere cosa richiede un provider, poi premi Ctrl+P per cambiare modello una volta configurato.',
    'keys.chat.repaint' => 'Cancella lo schermo e ridisegna il frame',
    'keys.unbound' => 'non associato',

    // --- C-EXT-1 (Claude Code hook dialect) 2026-10-27 ---
    'hooks.notice.advisory' => '⚠ L\'hook `async` Claude Code `{hook}` è terminato con {code}. Un hook `async` chiede di osservare una chiamata di tool anziché bloccarla, quindi non ha il potere di bloccarla e la chiamata è proseguita. Cosa ha detto: {reason}',
    'hooks.notice.claude_dialect' => '⚠ L\'hook Claude Code `{hook}` è terminato con {code}, che Claude Code interpreta come un reclamo non bloccante anziché una decisione, quindi la chiamata di tool è proseguita. Cosa ha detto: {reason}',
    'hooks.notice.said_nothing' => '(nessun output su stderr)',
    'hooks.notice.system_message' => '⚠ L\'hook `{hook}` ha lasciato un messaggio: {message}',

    // --- C-EXT-6.c (type: http hooks) 2026-10-30 ---
    // Every row names the hook and scheme://host only: never a path, a query,
    // or any header value, so an Authorization cannot ride out of the process
    // inside its own refusal.
    'hooks.http.deny_bad_url' => 'L\'hook HTTP `{hook}` è configurato con un URL non utilizzabile ({reason}); il target mostrato è {target}. Un hook che non può indicare dove sta andando non ha approvato questa chiamata.',
    'hooks.http.deny_scheme' => 'L\'hook HTTP `{hook}` indica {target}, che non è un URL http o https. candy-code contatta gli hook solo tramite questi due schemi, e la chiamata viene rifiutata anziché eseguita su un trasporto non verificato.',
    'hooks.http.deny_credentials' => 'L\'hook HTTP `{hook}` contiene credenziali nel suo URL ({target}). Una password scritta in un URL finisce nei log e nei proxy, quindi viene rifiutata; inviala come header il cui valore legge un nome `allowedEnvVars`.',
    'hooks.http.deny_blocked_target' => 'L\'hook HTTP `{hook}` non può essere consultato: {reason} ({target}). Gli indirizzi privati e link-local sono rifiutati dalla stessa regola di un fetch in uscita, e una guardia mai raggiunta non ha approvato questa chiamata.',
    'hooks.http.deny_unanswered' => 'L\'hook HTTP `{hook}` non ha risposto ({reason}); il target era {target}. Un hook non raggiungibile non ha approvato questa chiamata, quindi viene rifiutata.',
    'hooks.http.deny_header_injection' => 'L\'hook HTTP `{hook}` non può inviare il suo header `{field}`: il nome o il suo valore contiene un carattere di controllo, che è framing della richiesta anziché un valore di header. Nulla è stato inviato a {target} e la chiamata è rifiutata.',
    'hooks.http.notice_unanswered' => '⚠ L\'hook HTTP `{hook}` non ha risposto ({reason}), quindi non ha potuto bloccare la chiamata. È stato interrogato su {target}.',
    'hooks.http.reason_unreachable' => 'la connessione o la richiesta è scaduta entro il timeout dell\'hook stesso',
    'hooks.http.reason_oversized' => 'la risposta era più grande di {bytes} byte e non è terminata',
    'hooks.http.reason_no_status' => 'la risposta non conteneva una riga di stato HTTP',
    'hooks.http.reason_redirect' => 'ha effettuato un redirect, e una chiamata di hook non segue redirect',
    'hooks.http.reason_status' => 'la risposta non era uno stato 2xx',


    // --- C-EXT-6.d (type: prompt hooks) 2026-10-31 ---
    // Nothing was dialled and nothing was spent when these fire, so no row
    // carries a {target}: the hook either has no backend to be asked on, or
    // the answer it got is not a verdict.
    'hooks.prompt.deny_unanswered' => 'L\'hook prompt `{hook}` non ha risposto ({reason}). Un hook il cui verdetto non è mai stato restituito non ha approvato questa chiamata, quindi viene rifiutata.',
    'hooks.prompt.notice_unanswered' => '⚠ L\'hook prompt `{hook}` non ha risposto ({reason}), quindi non ha potuto bloccare la chiamata.',
    'hooks.prompt.reason_call_failed' => 'il modello non ha potuto essere interrogato',
    'hooks.prompt.reason_empty_verdict' => 'L\'hook prompt `{hook}` ha negato questa chiamata senza fornire un motivo.',
    'hooks.prompt.reason_no_backend' => 'questo avvio non ha un backend titolo su cui interrogarlo',
    'hooks.prompt.reason_no_prompt' => 'la voce contiene un prompt vuoto da interrogare',
    'hooks.prompt.reason_unparseable' => 'la sua risposta non era il singolo oggetto JSON con un booleano `ok` che è obbligato a fornire',

    // --- settings help (W3-B i18n migration) ---
    'settings.advisorModel.help' => 'Modello che il tool `Advisor` consulta per un secondo parere; non impostato — il default — non offre affatto il tool (non esiste un fallback a modello economico: il punto è un modello che hai scelto).',
    'settings.allowedTools.help' => 'Whitelist di nomi di tool o glob; non impostato offre ogni tool.',
    'settings.attribution.help' => '{"commit": "…", "pr": "…"}: il trailer e la riga PR che la guida git richiede.',
    'settings.autoCommit.help' => 'off, turn (un commit per turno, messaggio dal modello titolo) o edit (uno per Write/Edit); /undo lo annulla.',
    // C-SEC-7.e (owner ruling t212, option 3): the help states the implicit
    // default, the once-per-session announce, and the paid-call fact.
    'settings.autoReview.help' => 'In auto, una chiamata segnalata dal classificatore di sicurezza (diversa da un finding di sicurezza, che chiede sempre) viene revisionata dal modello titolo, che la consente, ti chiede o la nega. Attivo per default quando esiste un modello revisionabile, e un avvio che attiva quel default lo segnala una volta; imposta false per disattivarlo. Ogni revisione è una chiamata a modello a pagamento.',
    'settings.autoReviewModel.help' => 'Il `provider/model` su cui gira il revisore automatico, ad esempio `openai/gpt-4.1-mini`; vuoto significa il modello titolo. Un provider che non può essere costruito lascia il revisore spento con un avviso di avvio.',
    'settings.autoReviewScope.help' => 'Cosa `autoReview` invia al revisore: `shell` (il default) è ogni comando shell non di sola lettura che la lista di pattern ha superato; `writes` revisiona anche `Edit`, `Write`, `ApplyPatch` e `WebFetch`, con il diff in sospeso per i tool di scrittura; `all` revisiona ogni chiamata che la lista ha superato. Qualsiasi altra grafia si comporta come `shell`. Ogni revisione è una chiamata a modello a pagamento.',
    'settings.autoTest.help' => 'Dopo un turno che ha modificato un file, esegui `testCommand`; in caso di errore l\'output torna al modello, al massimo 3 volte per turno.',
    'settings.bashInteractiveIdleSeconds.help' => 'Secondi in cui un\'esecuzione Bash `interactive: true` può non stampare nulla prima di essere fermata come in attesa di un tasto.',
    'settings.bashMaxTimeoutSeconds.help' => 'Il `timeout` massimo che un comando Bash può richiedere; valori più grandi vengono limitati a questo.',
    'settings.bashSandbox.help' => 'Linux esegue Bash dentro bubblewrap; macOS lo esegue dentro un profilo Seatbelt tramite `sandbox-exec` — scrivibile solo nella root di lavoro (`no-network` taglia anche la rete). `allowlist` (Linux) instrada l\'uscita di rete attraverso il proxy di uscita dell\'avvio, che concede solo gli host elencati in `sandboxAllowedDomains`: con la lista EMPTY di default si comporta ESATTAMENTE come `no-network` finché non elenchi host, e anche una volta elencati, il traffico non-HTTP (ssh, porte database) e qualsiasi host non elencato fallisce. Su macOS `allowlist` viene applicato come `no-network`. Rifiuta i comandi quando la jail non può avviarsi; un valore non riconosciuto significa `no-network`, mai `off`.',
    'settings.bashSandboxNestedUserns.help' => 'Imposta a `true` per consentire a un comando `Bash` in sandbox di creare il proprio namespace utente, necessario per podman o buildah rootless e una sandbox Chromium. Il default `false` esegue bubblewrap con `--unshare-user --disable-userns`, bloccando la via di uscita usuale da una jail di mount; su un host il cui bubblewrap è troppo vecchio per quei flag la jail esegue il set semplice e la sua descrizione lo indica.',
    'settings.bashTimeoutSeconds.help' => 'Secondi in cui un comando Bash può girare quando il modello non passa un `timeout`; mai sopra il limite Bash.',
    'settings.chatToolTimeoutSeconds.help' => 'Budget di tempo reale di un batch di chiamate di tool che il percorso nativo chat (provider `command`) fork; i ritardatari vengono uccisi.',
    'settings.claudeMcpArgs.help' => 'Argomenti per quel binario; non impostato usa il default del trasporto.',
    'settings.claudeMcpBinary.help' => 'Percorso assoluto del binario `claude` che il trasporto claude-mcp può avviare.',
    'settings.claudeMcpEnv.help' => 'Variabili d\'ambiente letterali passate a quel binario.',
    'settings.compaction.autoPercent.help' => 'Quota di finestra alla quale gli scambi più vecchi vengono condensati automaticamente prima che il prompt venga inviato.',
    'settings.compaction.autoTokens.help' => 'Limite assoluto sul livello automatico e sul budget di step nel turno. 0 disattiva il limite.',
    'settings.compaction.blockPercent.help' => 'Quota di finestra oltre la quale un prompt viene rifiutato finché non si libera spazio; l\'unico livello che rifiuta.',
    'settings.compaction.blockTokens.help' => 'Limite assoluto sul livello bloccante; non impostato per default. Impostarlo consente a un limite di rifiutare prompt.',
    'settings.compaction.idleAuto.help' => 'Comprime una sessione inattiva oltre il livello durante l\'inattività anziché attendere il prompt successivo, usando il meccanismo del livello automatico (spend cap e thrash breaker si applicano). off: mai; hour: dopo la finestra completa di compaction.idleOfferSeconds; cacheTtl: poco prima della scadenza della prompt-cache del provider — un\'ora quando il provider segna cache breakpoint, circa 5 min per cache server-side, mai dove non riporta nulla in cache — una volta che la cronologia supera un pavimento sotto il livello automatico, perché il prompt successivo altrimenti prefillerebbe tutta la conversazione senza cache; sul tick di 60 secondi una cache da 5 min si comprime a circa 4 minuti di inattività. Costa una chiamata provider in background; richiede compaction.idleOfferSeconds sopra 0. Un bool continua a essere letto: true significa hour, false significa off.',
    'settings.compaction.idleOfferSeconds.help' => 'Una sessione oltre l\'intera finestra di contesto rimasta intatta per così tanto tempo riceve l\'offerta /compact anziché inviare il prompt. 0 non offre mai.',
    'settings.compaction.keepRecent.help' => 'Scambi utente/assistente più recenti che una compressione mantiene integralmente.',
    'settings.compaction.mode.help' => 'llm: il modello di riepilogo scrive i riepiloghi (l\'euristica è il suo fallback); heuristic: riepiloghi locali a una riga, mai una chiamata a modello; off: nulla si comprime da sé, /compact funziona ancora e il livello bloccante rifiuta ancora.',
    'settings.compaction.modelTokenCaps.help' => '{"<model>" o "<provider>/<model>": {"reminderTokens", "autoTokens", "blockTokens"}} che sovrascrive i tre limiti; 0 ne azzera uno.',
    'settings.compaction.refillLimit.help' => 'Compressioni automatiche consecutive che possono tornare subito sopra il loro livello, prompt non inviato, prima che il prompt successivo venga rifiutato anziché compresso di nuovo.',
    'settings.compaction.reminderPercent.help' => 'Quota di finestra alla quale il promemoria "considera la compressione" e il riepilogo in background anticipato iniziano; sotto il livello automatico.',
    'settings.compaction.reminderTokens.help' => 'Limite assoluto sul livello promemoria: scatta a min(percentage, questo). 0 disattiva il limite.',
    'settings.compaction.summaryAssistantChars.help' => 'Risposte dell\'assistente più lunghe di questo diventano "[exchanged information]" in una riga di riepilogo euristica.',
    'settings.compaction.summaryUserChars.help' => 'Caratteri di un messaggio utente che la riga di riepilogo euristica mantiene.',
    'settings.compaction.toolOutputChars.help' => 'Caratteri della metà assistant di uno scambio condensato mostrati al modello riassuntore.',
    'settings.connectTimeoutSeconds.help' => 'Limite per raggiungere un host del provider (DNS, TCP, TLS); non un timeout della richiesta.',
    'settings.contextPruning.compress.help' => 'manual offre Compress solo su un turno avviato con /compress, una chiamata; auto lo offre su ogni turno in cui il modello può potare.',
    'settings.contextPruning.iterationNudgeThreshold.help' => 'Risultati dei tool dall\'ultimo prompt dopo il quale un lungo ciclo di tool viene sollecitato a potare.',
    'settings.contextPruning.maxContextTokens.help' => 'Dimensione del contesto oltre la quale la riga più recente porta il promemoria più forte "prune now".',
    'settings.contextPruning.minContextTokens.help' => 'Dimensione del contesto sotto la quale il modello non viene mai sollecitato a potare; non deve superare la dimensione del promemoria rigido.',
    'settings.contextPruning.mode.help' => 'auto pota le righe sostituite all\'inizio di ogni turno; manual solo con /sweep; off non mostra tag di riferimento. /pruning lo sovrascrive per sessione.',
    'settings.contextPruning.nudgeFrequency.help' => 'Nuove righe che un promemoria attende dopo l\'ultimo, così non si ripete a ogni passo.',
    'settings.contextWindow.help' => 'Override della finestra di token: un conteggio per il modello del provider, oppure {"<model>": tokens}.',
    'settings.debug.commands.help' => 'Stampa su stderr ogni directory o file di comando personalizzato rifiutato, non solo il conteggio su una riga dell\'avvio.',
    'settings.debug.rules.help' => 'Stampa su stderr ogni directory o file di regole rifiutato.',
    'settings.debug.skills.help' => 'Stampa su stderr ogni file di skill saltato e ogni directory di skill rifiutata, non solo il conteggio su una riga dell\'avvio.',
    'settings.debug.stream.help' => 'Stampa su stderr la riga "onToken observer threw, detaching it" quando il sink di streaming di un embedder fallisce a metà turno.',
    'settings.diffPreviewRows.help' => 'Righe di un diff Edit o Write mostrate nella trascrizione prima che il resto venga riassunto.',
    'settings.diffStyle.help' => 'Layout del diff nella trascrizione: `auto` dipinge gli hunk affiancati su terminali larghi (120 colonne o più) e unificati altrove, `unified` sempre una colonna, `split` sempre due. I corpi dei diff sono colorati per token in entrambi i layout; la colonna dei marcatori `+`/`-` mantiene il suo colore.',
    'settings.disabledMcpServers.help' => 'Nomi di server o glob di `.mcp.json` (`untrusted_*`) che non vengono mai avviati, elencati o chiamati, per l\'agente principale e ogni sub-agente.',
    'settings.disabledRules.help' => 'Pacchetti di regole di livello utente tenuti fuori dal prompt dal primo turno.',
    'settings.disabledSkills.help' => 'Skill rimosse dalla discovery; ha anche la precedenza su enabledSkills.',
    'settings.disabledTools.help' => 'Nomi di tool o glob rimossi dall\'insieme di tool esposto al modello.',
    'settings.doubleEscSeconds.help' => 'Con quale rapidità il secondo Esc deve seguire il primo per annullare un turno in esecuzione.',
    'settings.embeddingModel.help' => 'Modello di embedding per il richiamo della memoria a ogni turno; non impostato classifica le note solo per parola chiave.',
    'settings.enabledSkills.help' => 'Skill i cui corpi completi viaggiano nel system prompt a ogni turno.',
    'settings.env.diffMaxBytes.help' => 'Byte che ciascuna delle due sezioni di git diff mantiene prima di essere troncata con una nota.',
    'settings.env.gitDiffAfterWrites.help' => 'Dopo un passo che ha scritto file, mostra i diff git staged e unstaged nel contesto del turno.',
    'settings.expandToolOutput.help' => 'Mostra l\'output completo di ogni chiamata di tool terminata nella trascrizione; Ctrl+O o un clic la collassano comunque.',
    'settings.extraBody.help' => 'Campi di richiesta di primo livello aggiunti a ogni richiesta del provider `custom`.',
    'settings.formatCommands.help' => 'Comando di formattazione post-edit per estensione di file ({"php": "vendor/bin/php-cs-fixer fix {file}"}); eseguito prima del lint post-edit e riscrive il file. Disattivato per impostazione predefinita.',
    'settings.formatAuto.help' => 'Consenti alla tabella di estensioni integrata (gofmt, rustfmt, ruff/black, shfmt, terraform fmt, il prettier di node_modules del progetto) di formattare un file modificato quando `formatCommands` non nomina un comando per la sua estensione. Le voci esplicite hanno la precedenza; un progetto ha comunque bisogno di `trustedProjectHooks`. Disattivato per impostazione predefinita.',
    'settings.globMaxMatches.help' => 'Percorsi che un Glob raccoglie prima che la sua esplorazione si fermi; il limite di output vincola comunque il risultato.',
    'settings.grepTimeoutSeconds.help' => 'Secondi che una ricerca Grep può eseguire prima di essere interrotta; i risultati trovati fino alla scadenza tornano come risultato parziale.',
    'settings.hooksDefaultTimeoutSeconds.help' => 'Secondi che una voce di hook senza `timeout:` può eseguire prima di essere interrotta e conteggiata come rifiuto.',
    'settings.includeGitInstructions.help' => 'Se la guida generica sui commit del tool Bash viaggia nel system prompt.',
    'settings.instructions.help' => 'Glob di file i cui contenuti diventano testo autorevole del system prompt.',
    'settings.instructions.walkToRoot.help' => 'Opt-in: legge anche i file di istruzioni sopra il marker .git più vicino, fino ma non inclusa la home directory. Solo livello utente; ogni lettura mantiene il proprio vincolo di contenimento e budget di dimensione.',
    'settings.instructionsExclude.help' => 'Glob di file di istruzioni da saltare, registrati come rifiuti; solo livello utente — un repository non può silenziare il proprio operatore. I file dentro il checkout corrispondono per percorso relativo al checkout; i file antenati e forzati fuori corrispondono per percorso assoluto, quindi `**/CLAUDE.local.md` raggiunge anche le copie antenate.',
    'settings.keybindings.help' => '{"shell.palette": "Ctrl+B"}: associa una chord EXTRA a un id di binding (il riferimento /keys li nomina) — Ctrl+<key>, Alt+<key>, Shift+<key>, o un tasto funzione isolato; la chord predefinita continua a funzionare. Presente ma inutilizzabile rifiuta l\'avvio; rimuovi il tasto per i binding predefiniti.',
    'settings.layout.help' => 'Il manifest dei pannelli docked; scritto dalla shell quando i pannelli si spostano.',
    'settings.lintCommands.help' => 'Comando di lint post-edit per estensione di file ({"php": "…", "js": false}); `php -l` è integrato.',
    'settings.lsp.help' => '{"php": {"command": "intelephense", "args": ["--stdio"]}}: server per diagnostica post-edit, outline di Read e il tool Lsp.',
    'settings.lspAutoDetect.help' => 'Avvia il language server nominato dall\'impronta del progetto (composer.json → intelephense, package.json + tsconfig.json → typescript-language-server, pyproject.toml o setup.py → pyright-langserver, go.mod → gopls, Cargo.toml → rust-analyzer) quando il suo binario è su PATH; le voci `lsp` manuali hanno la precedenza per linguaggio. Avviare un server esegue quel server e il codice di build nell\'albero aperto, quindi le impronte avviano server solo in progetti a cui hai dato fiducia per gli hook; una radice non fidata non ne avvia nessuno e registra il salto negli avvisi di avvio.',
    'settings.maxCheckpoints.help' => 'Checkpoint di turno a cui /rewind può tornare, per sessione; i più vecchi vengono potati oltre questo.',
    'settings.maxCostUsd.help' => 'Rifiuta nuovi turni quando la spesa riportata dal provider di un avvio raggiunge questo numero di dollari USA; non impostato significa nessun limite. /budget lo modifica solo per l\'avvio in esecuzione.',
    'settings.maxOutputTokens.help' => 'Limite di output per richiesta; non impostato non invia override e si applica il predefinito del provider.',
    'settings.maxToolSteps.help' => 'Chiamate al provider che un turno può effettuare; non impostato mantiene il predefinito del motore.',
    'settings.mcp.enabled.help' => 'Avvia i server MCP nominati dal .mcp.json di un progetto fidato; off non ne avvia nessuno e le superfici riportano l\'avvio come disabilitato.',
    'settings.mcp.lazySchemaTokens.help' => 'Token di schema che un server MCP può pubblicizzare prima che i suoi tool deferiscano a mcp_list/mcp_call; 0 non deferisce mai.',
    'settings.mcpResultCapBytes.help' => 'Massimo byte che la risposta di un tool MCP può passare al modello.',
    'settings.memory.autoConsolidate.help' => 'Salva fatti duraturi dai turni conclusi nella memoria, e incorpora il journal di compaction in essa (il dream pass); ciascuno è una chiamata fatturata.',
    'settings.memory.dreamIntervalSeconds.help' => 'Tempo minimo tra due dream pass per un progetto; ogni pass è un turno fatturato, in sola lettura.',
    'settings.memory.dreamProposeSkills.help' => 'Consenti al dream pass di proporre skill come bozze in ~/.candy-code/skills-proposed; nessuna è attiva finché non la accetti con /skills.',
    'settings.memory.entryMaxBytes.help' => 'Lunghezza massima della riga di indice di una nota prima di essere mostrata troncata; ridotta al budget di note utente se lo supera.',
    'settings.memory.projectNoteMaxBytes.help' => 'Dimensione massima di una nota di memoria di progetto quando viene scritta in .candy-code/memory/ del repository.',
    'settings.memory.promptMaxBytes.help' => 'Budget di byte per le righe di nota dell\'indice di memoria; il budget di note utente viene ridotto per rientrarvi.',
    'settings.memory.promptMaxEntries.help' => 'Massimo di note che l\'indice di memoria del prompt elenca, dalla più recente; le note utente contano al suo interno.',
    'settings.memory.userMaxBytes.help' => 'Budget di byte per le righe di ambito utente, dentro il budget totale.',
    'settings.memory.userMaxEntries.help' => 'Massimo di note cross-progetto (ambito utente) elencate per prime, dentro il conteggio delle note.',
    'settings.modelPrices.help' => 'USD per 1M token per modello ({"input": …, "output": …}), per il totale e il limite di spesa.',
    'settings.models.help' => 'Il modello da eseguire, per provider ({"<provider>": "<model id>"}); non impostato usa il predefinito del provider.',
    'settings.mouse.help' => 'Segnala il mouse a candy-code (clic, rotella, selezione); off restituisce al terminale il proprio copy-on-select.',
    'settings.mouseClicks.help' => 'Clic e trascinamenti agiscono su ciò che colpiscono; off mantiene la rotella e ignora i clic.',
    'settings.notices.transcriptLimit.help' => 'Massimo di avvisi di avvio posizionati come righe nella trascrizione; i restanti sono conteggiati in una riga "and N more", e stderr li riporta tutti.',
    'settings.notify.help' => 'off, bell (BEL) o osc9 (una notifica desktop): inviati quando un turno termina e quando l\'agente attende un\'approvazione.',
    'settings.paletteMru.help' => 'Quante righe di palette usate di recente vengono ricordate e classificate per prime; 0 non ne ricorda nessuna.',
    'settings.parallelToolCalls.help' => 'Esegui in parallelo le chiamate di tool in sola lettura di un turno.',
    'settings.parallelToolDeadlineSeconds.help' => 'Limite di tempo reale per un batch di chiamate di tool inviate in parallelo.',
    'settings.permissionMode.help' => 'Come le chiamate di tool sono soggette a gate. Mai prese da un file di progetto.',
    'settings.permissionRules.help' => 'Regole allow / deny / ask ordinate, confrontate con ogni chiamata di tool. Lo settings.json condiviso di un progetto fidato può contribuire voci deny / ask — solo restringendo.',
    'settings.permissions.autoAllowReadOnly.help' => 'Sotto default e accept-edits, esegui una riga Bash composta solo da comandi in sola lettura (ls, cat, grep, git log, …; nessuna ridirezione di file, nessuna sostituzione, cd solo dentro il progetto) senza chiedere. Un progetto può solo disattivarlo.',
    'settings.permissions.autoStrikeLimit.help' => 'Sotto auto, questo numero di chiamate bloccate di una categoria di fila trasforma la successiva in una domanda.',
    'settings.permissions.autoTotalLimit.help' => 'Sotto auto, una volta bloccate questo numero di chiamate in una sessione, ogni blocco successivo chiede a te.',
    'settings.pluginPaths.help' => 'Directory extra scansionate per bundle di plugin in formato Claude, oltre alle due radici installate; un valore può nominare un bundle stesso o un contenitore di bundle. Solo livello utente — un checkout non può iscrivere i propri plugin.',
    'settings.promptCache.keepWarm.help' => 'Ping di warmup consentiti per periodo di inattività; 0 (predefinito) è off. Ogni ping reinvia il prefisso congelato di una sessione inattiva con una riga di istruzione che chiede una risposta di un carattere, così il provider aggiorna la sua prompt cache prima che il TTL scada e il prompt successivo non precompila tutta la conversazione senza cache. Scatta solo dove il fold di cacheTtl è calato — sotto il suo pavimento o prima della sua ora — sullo stesso tick/alarm che il fold watch esegue già, mai a metà turno, mai più di uno alla volta, mai oltre questo conteggio per periodo. Sono chiamate fatturate a una sessione che nessuno sta guardando; il limite di spesa vincola comunque. Il conteggio finisce in /usage sotto `warm`.',
    'settings.promptCache.help' => 'Se i provider `vertex` e `bedrock` segnano i breakpoint della prompt cache.',
    'settings.promptSuggestionHistory.help' => 'Messaggi recenti (ognuno tagliato a 2000 caratteri) mostrati alla chiamata di suggerimento del prompt.',
    'settings.promptSuggestions.help' => 'Dopo ogni turno, chiedi al modello di titolo il messaggio che probabilmente invierai dopo e mostralo in grigio nella casella di input vuota (→ lo accetta).',
    'settings.provider.help' => 'A quale provider LLM la sessione parla; ogni prompt è inviato al suo host.',
    'settings.providerRetryAttempts.help' => 'Chiamate per richiesta al provider quando fallisce transitoriamente (rete, 5xx, 408, 429), la prima inclusa; 1 non ritenta mai.',
    'settings.providerRetryBaseBackoffMs.help' => 'Attesa prima del primo retry di una chiamata al provider fallita; ogni attesa successiva raddoppia.',
    'settings.providers.help' => 'Definizioni di provider per nome ({"<name>": {"type": …, "baseUrl": …, "apiKey": …, "model": …}}); ogni voce si sovrappone ai default di quel tipo. Solo livello utente: un progetto non deve mai spostare dove viene inviata la tua credenziale.',
    'settings.queueMode.help' => 'steer (l\'agente lo legge al suo prossimo passo), followup (inviato dopo il turno) o interrupt (ferma il turno al prossimo passo, poi invia). Tab accoda sempre.',
    'settings.readMaxBytes.help' => 'Limite massimo per una singola chiamata Read; la pagina sotto è la dimensione tipica di un risultato di lettura.',
    'settings.readPageBytes.help' => 'Byte che una pagina di Read può contenere, numeri di riga inclusi, qualunque cosa chieda `limit`.',
    'settings.readPageLines.help' => 'Righe che Read restituisce quando la chiamata non specifica `limit`.',
    'settings.reasoningEffort.help' => 'Livello di thinking inviato dove la coppia lo determina: openai (serie o e gpt-5, non le build -chat), anthropic e vertex (claude-3-7 e successivi; vertex risponde su entrambi i rami claude e gemini), gemini (2.5 e successivi), sglang (inoltrato a ogni richiesta), bedrock (id claude, come budget di thinking), codex e claude-code (livelli nominati inoltrati alla CLI); non impostato o non riconosciuto non richiede nulla. `/effort` lo imposta e lo azzera.',
    'settings.redactToolOutput.help' => 'Disattivato di default: l\'output degli strumenti consolidato viene salvato in history e sessions.db esattamente come è tornato. Quando attivo, ogni risultato di strumento passa attraverso lo stesso redattore che protegge memoria e `/share` una volta consolidato — le credenziali riconosciute diventano `[REDACTED]` nei byte persistiti e in ciò che i turni successivi ripresentano al modello (lo strumento stesso continua a eseguire invariato). I campi image, document e usage passano intatti. `/export` non aggiunge redazione propria: stampa esattamente ciò che è stato salvato, quindi tutto ciò salvato prima di attivare questa opzione resta grezzo.',
    'settings.references.help' => 'Un elenco di `[{"path": "…", "name": "…"}]` di directory fuori dal workspace che Read, Grep, Glob e Ls possono anche aprire, in sola lettura; ciascuna è pubblicizzata nel blocco `<env>` con una mappa limitata di ciò che contiene. Il jail del workspace resta invariato per Write, Edit e Bash — un riferimento non allarga mai cosa si può scrivere. Solo livello utente: un repository checkout non può aggiungere una radice di lettura. Un percorso mancante o non-directory, o uno dentro la radice di sessione, viene rifiutato all\'avvio con un avviso.',
    'settings.repoMap.enabled.help' => 'Inserisci nel system prompt la mappa di dove vive il codice (pacchetti e directory sorgente PSR-4).',
    'settings.repoMap.maxBytes.help' => 'Budget in byte per ciascuna delle due sezioni della mappa del repo; le voci oltre il limite sono contate, non elencate.',
    'settings.requireReadBeforeWrite.help' => 'Attivo, `Edit`, una `Write` che sovrascrive un file esistente e una sezione `ApplyPatch` che modifica, sposta o elimina un file sono rifiutati finché il modello non ha letto quel file in questa sessione; la creazione di nuovi file non è mai bloccata. Disattivato di default: i file che il modello ha letto restano protetti dalla regola di modifica su disco in entrambi i casi.',
    'settings.resumeCostWarnUsd.help' => 'Dopo un resume obsoleto il primo prompt viene trattenuto una volta quando il reinvio della history è stimato costare almeno questo numero di dollari senza cache; premi Invio di nuovo per inviare comunque, o /compact prima. 0 disattiva il trattenimento.',
    'settings.sandboxAllowedDomains.help' => 'Gli host raggiungibili dal jail `allowlist`: nomi semplici (`example.com`), wildcard `*.example.com` e forme `host:port` (predefinito: nessuno). Usato solo quando `bashSandbox` è `allowlist` su Linux; con una lista VUOTA `allowlist` si comporta ESATTAMENTE come `no-network`. Il proxy di uscita concede HTTP(S) e null\'altro — ogni host non elencato riceve 403, e il traffico non-HTTP (ssh, porte database) fallisce. Una voce malformata viene IGNORATA in fase di enforcement: un typo può solo restringere la concessione, mai ampliarla. Solo livello utente: un repository checkoutato non deve aprire un buco nel jail in cui è arrivato. macOS applica `allowlist` come `no-network` — il ramo loopback-port è un follow-up tracciato.',
    'settings.sandboxScope.help' => 'Quali comandi fuori dal percorso tool entrano nel jail `bashSandbox`: `hooks`, `lint`, `format`, `test`, `lsp`, `mcp` (predefinito: nessuno). Attivo solo mentre `bashSandbox` non è `off` — la lista dice chi condivide il jail, mai se ne esiste uno. Una voce non riconosciuta equivale a OGNI scope (il più restrittivo, come un valore `bashSandbox` non riconosciuto), e l\'audit delle impostazioni lo segnala. Un jail che non può avviarsi rifiuta il lavoro anziché eseguirlo libero: gli script hook negano, lint, format e test saltano con il motivo, e un server LSP o MCP stdio in jail non viene avviato. Le voci `lsp` e le voci MCP di livello utente portano un opt-out `"sandbox": false` per server; gli opt-out MCP di livello progetto vengono ignorati.',
    'settings.screenReader.help' => 'Presentazione per utenti screen-reader. On, l\'app elimina la decorazione che un lettore non può narrare — lo spinner dell\'agente si fissa su un singolo frame statico, e i frame a caratteri di disegno, la selezione menu solo in video inverso e simili cedono il passo a testo semplice e un segnale acustico mentre ogni superficie onora la commutazione. Off è il terminale dipinto come al solito. Il tuo personale setting di accessibilità, come la modalità vim della casella di bozza: un progetto checkoutato non può cambiarlo. Si applica alla prossima lettura dopo il salvataggio — live, senza ricaricare.',
    'settings.rules.standingMaxBytes.help' => 'Budget in byte, incorniciato e con escape, per i file di regole inseriti per intero in ogni prompt; una regola oltre il limite viene indicata da una sola riga puntatore.',
    'settings.scrollWheelLines.help' => 'Righe di trascrizione che un tick della rotellina fa scorrere.',
    'settings.sd.apiKey.help' => 'Chiave Bearer inviata al server Stable Diffusion, se ne richiede una; preferisci la forma segnaposto `${VAR}` a un valore letterale.',
    'settings.sd.baseUrl.help' => 'URL base HTTP di un webui Stable Diffusion compatibile con AUTOMATIC1111 (`http://127.0.0.1:7860`); prompt, immagini e chiave API escono tutti da lì.',
    'settings.sd.defaultModel.help' => 'ID modello con cui le richieste di generazione iniziano; il server tiene la scelta per sé se non impostato.',
    'settings.sd.presets.help' => 'Bundle di parametri nominati che il form media offre; la forma è propria della pipeline media, opaca al livello impostazioni.',
    'settings.sd.savePattern.help' => 'Template di nome file per i media salvati; i token `[date]`, `[time]`, `[seed]` e `[number]` si riempiono al momento del salvataggio.',
    'settings.sd.timeoutSeconds.help' => 'Secondi in cui una richiesta di generazione può girare prima di essere abbandonata; la diffusione su una GPU debole richiede di routine minuti.',
    'settings.secretEnvAllowlist.help' => 'Nomi di variabili a forma di credenziale (o glob) che Bash, Grep e gli script hook ereditano ancora.',
    'settings.server.allowBypass.help' => 'Se le sessioni server possono girare in bypass-permissions o dont-ask (stesso effetto di --allow-bypass).',
    'settings.server.allowedHosts.help' => 'Nomi host (o host:port) a cui il server risponde oltre ai nomi loopback e ai propri indirizzi, es. quelli di un reverse proxy.',
    'settings.server.allowedIps.help' => 'IP client o range CIDR autorizzati a connettersi oltre al loopback; chiunque altro viene rifiutato con 403 prima del sign-in. Vuoto: nessun filtro indirizzi.',
    'settings.server.allowedOrigins.help' => 'Origini browser extra (http(s)://host[:port]) che il server accetta oltre alla propria.',
    'settings.server.askTimeoutSeconds.help' => 'Secondi in cui una domanda di permesso attende un client prima di essere rifiutata; 0 attende per sempre.',
    'settings.server.browseRoot.help' => 'La directory a cui server.dirBrowse è confinato (stesso effetto di --browse-root); non impostato è la tua home directory.',
    'settings.server.dirBrowse.help' => 'Consenti ai client autenticati di elencare i nomi di directory sotto server.browseRoot e avviare sessioni lì (stesso effetto di --allow-dir-browse). Off per impostazione predefinita.',
    'settings.server.clientTools.help' => 'Consenti ai client con scope Write di registrare tool tramite tools.client.register così che il modello possa chiamare codice eseguito nel client stesso (tool client__*). Off per impostazione predefinita.',
    'settings.server.drainSeconds.help' => 'Secondi in cui un server in arresto attende i turn in esecuzione prima di annullarli; 0 si ferma subito.',
    'settings.server.host.help' => 'L\'indirizzo a cui `serve` si vincola. Qualsiasi cosa diversa dal loopback richiede anche --allow-remote al lancio.',
    'settings.server.maxConcurrentTurns.help' => 'Turn che un server esegue in parallelo tra le sue sessioni; uno in più viene rifiutato come occupato (ritentabile).',
    'settings.server.maxOpenSessions.help' => 'Sessioni che un server tiene aperte in parallelo; oltre il limite viene rilasciata quella idle meno recentemente usata.',
    'settings.server.port.help' => 'La porta a cui `serve` si vincola; 0 ne sceglie una libera.',
    'settings.server.trustedProxies.help' => 'IP o CIDR di cui il server crede X-Forwarded-For / X-Forwarded-Proto.',
    'settings.serviceTier.help' => 'Corsia premium inviata dove la coppia la modella: openai chiede `service_tier: "priority"` su entrambi i rami Chat e Responses, anthropic chiede `speed: "fast"` (solo la famiglia claude-opus-5-5 GA e le famiglie claude-opus-5 / claude-opus-4-8 research-preview, il cui beta header obbligatorio viaggia automaticamente); non impostato o non riconosciuto non chiede nulla. La modalità fast fattura un premium che nessuna tabella prezzi per-modello può derivare: mentre una coppia a livelli è attiva i suoi turn finiscono sul registro come non prezzati, mai come un tasso ipotizzato. Si applica al lancio e a ogni rebuild di provider o modello.',
    'settings.sessionRetentionDays.help' => 'Ogni lancio elimina le sessioni senza nome e non fissate inattive da questo numero di giorni e dice quali; 0 (il predefinito) conserva tutto.',
    'settings.sessions.autoTitle.help' => 'Nomina ogni nuova sessione dal suo primo turn con una sola chiamata sul modello dei titoli; off la lascia senza nome fino a /rename.',
    'settings.sessions.awayRecap.help' => 'Quando il terminale riporta il focus dopo che sei stato via tre minuti o più, stampa un riepilogo di dove la sessione si era fermata (una chiamata sul modello dei titoli per assenza); off lascia il ritorno silenzioso. `/recap` ne chiede uno in qualsiasi momento.',
    'settings.skills.listingMaxBytes.help' => 'Budget in byte per l\'intero elenco skill nel system prompt; le skill oltre il limite collassano in una riga "N altre skill".',
    'settings.skills.pathNudges.help' => 'Quando un tool tocca un file coperto da una skill con scope di percorso, ricorda al modello che quella skill esiste, una volta per skill.',
    'settings.statusLine.help' => '{"type": "command", "command": "…", "refreshSeconds": 2}: un comando shell la cui output dipinge la barra di stato, rieseguito ogni refreshSeconds (da 2 a 3600, predefinito 2). Riceve la sessione come un documento JSON su stdin (session_id, cwd, model, workspace, version, cost, più extra candy_code); un comando che non legge mai stdin viene comunque eseguito.',
    'settings.streamHeaderTimeoutSeconds.help' => 'Secondi che un server streaming connesso può impiegare per inviare le sue intestazioni di risposta; mai un timeout totale della richiesta.',
    'settings.streamIdleTimeoutSeconds.help' => 'Secondi in cui una singola lettura di una risposta streaming può attendere byte prima che la connessione sia dichiarata morta; per lettura, mai un totale.',
    'settings.subagentMaxActive.help' => 'Esecuzioni delegate che una sessione può avere in corso in parallelo, ogni livello, membro e agente in background conteggiato; oltre il limite una chiamata `Task` viene rifiutata. Non impostato — il predefinito — o 0 non pone alcun tetto.',
    'settings.subagentMaxConcurrent.help' => 'Chiamate `Task` di un batch che girano in parallelo (le restanti attendono uno slot libero), e la larghezza di ogni pool di agenti. Non impostato — il predefinito — o 0 non pone alcun tetto.',
    'settings.subagentMaxDepth.help' => 'Livelli sotto la sessione in cui un\'esecuzione delegata può stare; un\'esecuzione all\'ultimo livello non ottiene `Task`. 1 consente ai sub-agente di non delegare oltre.',
    'settings.subagentMaxTurns.help' => 'Tetto di step per un sub-agente — una delega `Task`, uno stage di workflow o un\'esecuzione `executeAgents` — il cui preset non dichiara `maxTurns`.',
    'settings.subagentModel.help' => 'Modello su cui gira un sub-agente delegato quando il suo preset dice `inherit`; non impostato segue il modello della sessione.',
    'settings.summaryModel.help' => 'Modello che scrive i riepiloghi di compaction; non impostato usa il modello proprio della conversazione, che riusa la prompt cache.',
    'settings.symbolMap.enabled.help' => 'Inserisci la mappa del repo a livello di simbolo classificata nel system prompt, catturata una volta per sessione.',
    'settings.temperature.help' => 'Temperatura di campionamento che il provider `custom` invia quando una richiesta non ne nomina una.',
    'settings.terminalBackground.help' => 'Cosa il tema adattivo assume dietro il testo: auto chiede al terminale (OSC 11, poi COLORFGBG); light o dark lo dichiarano apertamente.',
    'settings.testCommand.help' => 'Comando shell che esegue i test del progetto, nella radice del progetto (`composer test`, `pytest -q`); ciò che `autoTest` esegue.',
    'settings.theme.help' => 'Tema di colori; /theme e la palette lo cambiano live. I temi personalizzati si caricano da file JSON sotto ~/.candy-code/themes.',
    'settings.thinkingBudget.help' => 'Budget di token di thinking: `thinkingConfig` di Gemini sul provider `vertex`; extended thinking sul provider `anthropic`, dove il pavimento dell\'API Messages è 1024 (0 o non impostato significa off su entrambi i rami). I token di thinking fatturano come output.',
    'settings.titleModel.help' => 'Modello che nomina le sessioni e scrive suggerimenti di prompt; non impostato usa il default ausiliario economico del tipo di provider prima del modello del blocco.',
    'settings.transcriptJsonl.help' => 'Specchia ogni trascrizione committata in un journal JSONL append-only sotto `~/.candy-code/transcripts/<project>/` (file 0600), e passa agli script hook una chiave stdin `transcript_path` che lo indica. Il journal contiene la conversazione grezza e cresce senza limiti; letto al lancio, quindi una modifica si applica al prossimo avvio.',
    'settings.toolInstructionCapBytes.help' => 'Massimi byte di un corpo CLAUDE.md/AGENTS.md governante che un risultato Edit, Write o ApplyPatch può portare; il resto viene tagliato con un marcatore.',
    'settings.toolOutputCapBytes.help' => 'Massimi byte che un singolo risultato Bash, Grep, Glob, Lsp o WebFetch può passare al modello; ciò che viene tagliato è salvato in un file che il risultato nomina.',
    'settings.toolOutputPreviewLines.help' => 'Righe di un risultato tool collassato mostrate nella trascrizione; Ctrl+O espande il resto.',
    'settings.toolSpillCaptureBytes.help' => 'Massimo dell\'output di un comando Bash (per stream) trattenuto in memoria e salvato nel file di spill quando il risultato viene tagliato; mai sotto il tetto di output.',
    'settings.toolSpillMinCapBytes.help' => 'Il più piccolo tetto di risultato al quale un risultato tool tagliato viene salvato in un file; sotto di esso il taglio viene annunciato e il resto scartato.',
    'settings.toolSpillWindowPercent.help' => 'La più grande quota della finestra di contesto che un singolo risultato tool può occupare; oltre di essa il risultato viene salvato in un file e al modello mostrati inizio e fine.',
    'settings.trustedProjectCommands.help' => 'Radici di progetto i cui comandi slash possono eseguire blocchi shell !`cmd`.',
    'settings.trustedBundleCommands.label' => 'Comandi bundle affidabili',
    'settings.trustedBundleCommands.help' => 'Nomi di bundle di plugin i cui file di comando possono eseguire blocchi shell !`cmd`; ogni comando è comunque giudicato dal gate dei permessi. I nomi corrispondono al nome del manifesto del bundle stesso, e contano solo le installazioni a livello utente — un checkout di progetto non può concedere la shell a sé stesso, nemmeno spacciandosi per un nome elencato. L\'opt-in non è un bypass: al gate solo una regola Deny rifiuta, e una regola che il gate valuta Ask esegue senza presidio — l\'espansione non ha alcun prompt da mostrare. Vuoto per impostazione predefinita, quindi i comandi bundle non eseguono alcuna shell.',
    'settings.mcpPromptShell.label' => 'Shell prompt MCP',
    'settings.mcpPromptShell.help' => 'Chiavi di server MCP i cui corpi prompt possono eseguire blocchi shell !`cmd`; ogni comando è comunque giudicato dal gate dei permessi. I nomi corrispondono alla chiave che la configurazione utente assegna al server. Solo livello utente; vuoto per impostazione predefinita, quindi i prompt recuperati non eseguono alcuna shell. L\'opt-in non è un bypass: al gate solo una regola Deny rifiuta, e una regola che il gate valuta Ask esegue senza presidio — l\'espansione non ha alcun prompt da mostrare.',
    'settings.trustedProjectHooks.help' => 'Radici di progetto i cui .candy-code/hooks.yaml possono essere eseguiti.',
    'settings.trustedProjectMcp.help' => 'Radici di progetto i cui server .mcp.json possono essere avviati.',
    'settings.trustedProjectSettings.help' => 'Radici di progetto i cui .candy-code/settings*.json possono impostare le chiavi di livello progetto.',
    'settings.turnIdleTimeoutSeconds.help' => 'Secondi in cui un turn in esecuzione può procedere senza alcun progresso prima di essere fermato come bloccato; tempo di inattività, mai un totale.',
    'settings.ui.imageRenderMode.help' => 'Come le immagini generate vengono dipinte nel terminale; `auto` sceglie il miglior protocollo che il terminale riporta.',
    'settings.ui.mediaDisplayOverrides.help' => 'Regolazioni di visualizzazione per modalità di rendering (tetti di dimensione, fallback); le chiavi sono le parole della modalità di rendering, i valori le manopole di visualizzazione.',
    'settings.vimMode.help' => 'Modifica NORMAL/INSERT nella casella di bozza (i a I A o O Esc, h j k l w b e 0 $ x, dd D cc C yy y p P v V, oggetti di testo di" da( ciw, conteggi 3dd d2w): moti, modifica, cancellazione e yank in NORMAL, digitazione verbatim in INSERT. Una modalità, non binding — non appare mai in /keys. Si applica al prossimo tasto dopo il salvataggio.',
    'settings.voice.apiKey.help' => 'Chiave Bearer inviata all\'endpoint di trascrizione, se ne richiede una; preferisci la forma segnaposto `${VAR}` a un valore letterale.',
    'settings.voice.baseUrl.help' => 'URL base HTTP di un endpoint di trascrizione compatibile con OpenAI (un `/v1` finale viene mantenuto); la registrazione presa esce da lì e da nessun\'altra parte. Nessun default: l\'input vocale resta OFF finché questo non è impostato nel livello utente.',
    'settings.voice.language.help' => 'Codice BCP-47 (`en`, `de`) che forza la lingua di trascrizione; non impostato lascia che l\'endpoint la rilevi.',
    'settings.voice.maxSeconds.help' => 'Tetto rigido in secondi su una singola registrazione (5-600, predefinito 120). Il tetto viaggia nell\'argomento del registratore, così una presa orfana si ferma da sola.',
    'settings.voice.model.help' => 'ID modello inviato con ogni richiesta di trascrizione; `whisper-1` risponde sugli endpoint compatibili con OpenAI.',
    'settings.watchFiles.help' => 'Invia un prompt quando un file salvato contiene un commento che termina in AI! (apporta una modifica) o AI? (rispondi a una domanda); i commenti AI semplici viaggiano come contesto. Interrogato mentre la chat è idle; solo i commenti salvati dopo il lancio scattano, ciascuno una volta. Solo sessioni terminale: il watcher gira nel processo terminale, quindi una sessione ospitata da `candy-code serve` non sorveglia file.',
    'settings.webFetchMaxBytes.help' => 'Massimo di un corpo scaricato trattenuto in memoria; un vincolo di memoria, il tetto di output è ciò che raggiunge il modello.',
    'settings.webFetchTimeoutSeconds.help' => 'Secondi in cui una lettura socket di WebFetch può stallare prima che il fetch fallisca.',
    'settings.webSearchBackend.help' => 'Quale servizio di ricerca WebSearch interroga: `searxng` (il predefinito) invia ogni query all\'`webSearchEndpoint` configurato; `brave`, `tavily` ed `exa` chiamano invece l\'host fisso di quel servizio e ciascuno richiede la propria API key nell\'ambiente (`BRAVE_SEARCH_API_KEY`, `TAVILY_API_KEY`, `EXA_API_KEY`), senza modo di puntarli a un altro URL.',
    'settings.webSearchEndpoint.help' => 'URL di ricerca di un\'istanza SearXNG di cui ti fidi (`https://searx.example.org/search`); ogni query WebSearch viene inviata lì.',
    'settings.webSearchMaxResults.help' => 'Risultati che un digest WebSearch elenca, ciascuno un titolo, URL e snippet.',
    'settings.webSearchTimeoutSeconds.help' => 'Secondi che una singola richiesta di ricerca può impiegare.',
    'settings.webhooks.help' => 'Mappa da nome hook a {secret, prompt, permissionMode?, rate?}; POST /api/hooks/{name} inserisce poi il corpo (con escape come non fidato) nel prompt e avvia una sessione in background. Vuota (predefinito) non monta nulla. rate è N consegne al minuto per indirizzo, e per hook nel complesso. bypass-permissions viene rifiutato per gli hook al lancio; un hook senza modalità gira nel più restrittivo tra la modalità del server e il default. Una riga può anche nominare signature: {scheme: "github-sha256"|"hmac-sha256", header?, deliveryHeader?}: la rotta verifica allora un HMAC-SHA256 del corpo grezzo (sha256=<hex>) con il secret della riga tramite l\'header signature, al posto del secret nell\'header custom, perché GitHub non può inviare header custom; le firme fallite alimentano lo stesso lockout per-hook, e un id di consegna già visto (X-GitHub-Delivery di default per lo schema GitHub; il deliveryHeader configurato per uno generico) risponde {"ok": true, "duplicate": true} senza avviare una seconda sessione.',
    'settings.webhooksOut.help' => 'Mappa da nome endpoint a {url, secret, events}; events è una lista non vuota tratta da turn.completed, session.ended, permission.asked e schedule.fired. Vuota (predefinito) non apre alcuna uscita. Letta solo dal livello UTENTE — una configurazione di progetto o bundle non può mai aggiungere un endpoint in uscita. url deve essere https, o http solo quando il suo host letterale è localhost o un indirizzo loopback, e non porta mai userinfo; secret è di almeno 16 caratteri e firma ogni consegna con HMAC-SHA256 come X-Candy-Code-Signature (sha256=<hex> sul corpo esatto) abbinato a X-Candy-Code-Timestamp. La consegna è asincrona sul loop degli eventi — i dispatch non aspettano mai una risposta: un confine di connessione di 2 secondi e un tetto di rete per POST di 10 secondi vincolano ogni consegna (limiti webhook, non un timeout di richiesta LLM), i fallimenti di trasporto e le risposte 5xx salgono una scala di retry 2/8/30 secondi, le risposte 4xx e di redirect sono definitive la prima volta perché i redirect vengono rifiutati anziché seguiti, e una coda limitata di 128 consegne in volo scarta i nuovi dispatch in caso di overflow anziché far crescere la memoria. Letta al lancio; modificare la mappa ha effetto al riavvio.',
    'settings.webhooksOut.refuse' => 'webhooksOut nella configurazione utente non è utilizzabile: {reason}. Rifiuto di avviare anziché consegnare a un endpoint a metà verificato — correggi la mappa, o rimuovi la chiave per girare senza webhook in uscita.',
    // --- end settings help ---

