    'session.import.refusal.not_readable' => 'import: {path} non è un file leggibile, quindi non è stato importato nulla',
    'session.import.refusal.source_shrank' => 'import: la fonte contiene ora meno righe di trascrizione rispetto all\'ultima importazione, e una trascrizione ridotta viene rifiutata anziché riscritta',
